const CODE={"tpl-h": "#ifdef DEVICE_DISPLAY_MODULE\n#pragma once\n/**\n * @file        WidgetMyModule.h\n * @brief       Template for a display widget: card, values, history (rename MyModule, replace the values)\n * @copyright   Copyright (c) 2026, Erkan Çolak (erkan@colak.de)\n *              Licensed under GNU GPL v3.0\n **/\n#include \"Widget.h\"\n#include <cstdint>\n#include <string>\n\n/**\n * @brief Three read-only pages: status card, values, history.\n * The WidgetsManager rotates and flips the pages; the widget only draws what the module already holds.\n */\nclass WidgetMyModule : public Widget\n{\n  public:\n    const std::string logPrefix() { return \"mym\"; }\n    WidgetMyModule(uint32_t displayTime, WidgetFlags action);\n\n    void setup() override;\n    void start() override;\n    void stop() override;\n    void pause() override;\n    void resume() override;\n    void loop() override;\n\n    inline const WidgetState getState() const override { return _state; }\n    inline const std::string getName() const override { return _name; }\n    inline void setName(const std::string &name) override { _name = name; }\n    inline uint32_t getDisplayTime() const override { return _displayTime; }\n    inline WidgetFlags getAction() const override { return _action; }\n    inline void setDisplayTime(uint32_t displayTime) override { _displayTime = displayTime; }\n    inline void setAction(uint8_t action) override { _action = static_cast<WidgetFlags>(action); }\n    inline void addAction(uint8_t action) override { _action = static_cast<WidgetFlags>(_action | action); }\n    inline void removeAction(uint8_t action) override { _action = static_cast<WidgetFlags>(_action & ~action); }\n    inline void setDisplayModule(i2cDisplay *displayModule) override { _display = displayModule; }\n    inline i2cDisplay *getDisplayModule() const override { return _display; }\n\n    // Pages: page 0 is the card; without auto paging the rotation shows only page 0.\n    size_t getPageCount() const override { return PAGE_COUNT; }\n    size_t getCurrentPage() const override { return _page; }\n    void setPage(size_t page) override;\n    void nextPage() override { setPage((_page + 1) % PAGE_COUNT); }\n    void prevPage() override { setPage((_page + PAGE_COUNT - 1) % PAGE_COUNT); }\n\n  private:\n    enum Page : uint8_t\n    {\n        PAGE_CARD = 0,\n        PAGE_VALUES,\n        PAGE_HISTORY,\n        PAGE_COUNT\n    };\n\n    static constexpr uint32_t REDRAW_INTERVAL_MS = 500;\n\n    WidgetState _state = WidgetState::STOPPED;\n    uint32_t _displayTime;\n    WidgetFlags _action;\n    i2cDisplay *_display = nullptr;\n    std::string _name = \"MyModule\"; // rotation settings are stored by this name: never rename it later\n    size_t _page = 0;\n    uint32_t _lastDraw = 0;\n    bool _forceRedraw = true;\n\n    void drawPage();\n    void drawCard(Adafruit_SSD1306 &d);\n    void drawValues(Adafruit_SSD1306 &d);\n    void drawHistory(Adafruit_SSD1306 &d);\n};\n#endif // DEVICE_DISPLAY_MODULE\n", "tpl-cpp": "#ifdef DEVICE_DISPLAY_MODULE\n/**\n * @file        WidgetMyModule.cpp\n * @brief       Template for a display widget: card, values, history (rename MyModule, replace the values)\n * @copyright   Copyright (c) 2026, Erkan Çolak (erkan@colak.de)\n *              Licensed under GNU GPL v3.0\n **/\n#include \"WidgetMyModule.h\"\n#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\n#include \"OpenKNX.h\"\n#include <stdio.h>\n\nnamespace Ui = OpenKNX::Ui;\n\n// ---- Values: replace with the getters of your module. The widget keeps no copies and no buffers. ----\nstatic bool moduleOk() { return true; }\nstatic int16_t temperatureTenths() { return 215; }  // 21.5 C\nstatic uint8_t humidityPercent() { return 48; }\nstatic uint8_t historyCount() { return 60; }         // samples the module keeps, one per minute\n/** @brief Graph reader: sample i (0 = oldest) as 0..1000 permille, Ui::GraphGap for \"no value\". */\nstatic uint16_t historyAt(void *, uint8_t i) { return (uint16_t)(400 + (i * 37) % 300); }\n// -----------------------------------------------------------------------------------------------------\n\n/** @brief Tenths as \"-0.5\": the sign also below one degree, where t / 10 is 0. */\nstatic const char *tenthsText(char *b, size_t n, int16_t t)\n{\n    const unsigned a = t < 0 ? (unsigned)-t : (unsigned)t;\n    snprintf(b, n, \"%s%u.%u\", t < 0 ? \"-\" : \"\", a / 10, a % 10);\n    return b;\n}\n\n/** @brief Card symbol, drawn into x44..83 y1..27 (a 40x27 field above the word). */\nstatic void drawSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawRoundRect(52, 2, 24, 24, 3, WHITE);\n    d.setCursor(56, 10);\n    d.print(\"MOD\");\n}\n\nWidgetMyModule::WidgetMyModule(uint32_t displayTime, WidgetFlags action)\n    : _displayTime(displayTime), _action(action)\n{\n}\n\nvoid WidgetMyModule::setup()\n{\n    if (_display == nullptr)\n        logErrorP(\"Display is NULL.\");\n}\n\nvoid WidgetMyModule::start()\n{\n    _state = WidgetState::RUNNING;\n    _forceRedraw = true;\n}\n\nvoid WidgetMyModule::stop()\n{\n    _state = WidgetState::STOPPED;\n}\n\nvoid WidgetMyModule::pause()\n{\n    if (_state == WidgetState::RUNNING)\n        _state = WidgetState::PAUSED;\n}\n\nvoid WidgetMyModule::resume()\n{\n    if (_state == WidgetState::PAUSED)\n    {\n        _state = WidgetState::RUNNING;\n        _forceRedraw = true;\n    }\n}\n\nvoid WidgetMyModule::loop()\n{\n    if (_state != WidgetState::RUNNING || !_display)\n        return;\n    // Non-blocking: redraw at most every REDRAW_INTERVAL_MS, at once after a page change.\n    const uint32_t now = millis();\n    if (_forceRedraw || now - _lastDraw >= REDRAW_INTERVAL_MS)\n    {\n        _lastDraw = now;\n        _forceRedraw = false;\n        drawPage();\n    }\n}\n\nvoid WidgetMyModule::setPage(size_t page)\n{\n    if (page >= PAGE_COUNT)\n        page = PAGE_COUNT - 1;\n    if (page != _page)\n    {\n        _page = page;\n        _forceRedraw = true;\n    }\n}\n\nvoid WidgetMyModule::drawPage()\n{\n    Adafruit_SSD1306 &d = *_display->display;\n    Ui::begin(d); // size 1, white, no wrap, cp437 off: never inherit the state of another widget\n    d.clearDisplay();\n    switch (_page)\n    {\n        case PAGE_VALUES: drawValues(d); break;\n        case PAGE_HISTORY: drawHistory(d); break;\n        default: drawCard(d); break;\n    }\n    _display->displayBuff();\n}\n\n/** @brief Page 1: symbol, badge, one word in size 2, one detail line. */\nvoid WidgetMyModule::drawCard(Adafruit_SSD1306 &d)\n{\n    char detail[24], t[8];\n    snprintf(detail, sizeof(detail), \"%s C  %u %%\", tenthsText(t, sizeof(t), temperatureTenths()), (unsigned)humidityPercent());\n    if (moduleOk())\n        Ui::statusCard(d, drawSymbol, Ui::kBadgeOk, \"Ready\", detail);\n    else\n        Ui::statusCard(d, drawSymbol, Ui::kBadgeError, \"Error\", \"Check sensor\");\n    Ui::pageDots(d, PAGE_COUNT, PAGE_CARD);\n}\n\n/** @brief Page 2: label and value rows in the 10 px rhythm (y14, 24, 34, ...). */\nvoid WidgetMyModule::drawValues(Adafruit_SSD1306 &d)\n{\n    char b[24], t[8];\n    Ui::header(d, \"Values\", PAGE_COUNT, PAGE_VALUES);\n    snprintf(b, sizeof(b), \"%s C\", tenthsText(t, sizeof(t), temperatureTenths()));\n    Ui::row(d, 0, \"Temp\", b);\n    snprintf(b, sizeof(b), \"%u %%\", (unsigned)humidityPercent());\n    Ui::row(d, 1, \"Hum\", b);\n    Ui::rowIcon(d, 3, moduleOk() ? Ui::kRowOk : Ui::kRowErr, \"Sensor\", moduleOk() ? \"ok\" : \"error\");\n}\n\n/** @brief Page 3: big value and the history the module keeps (60 samples, 2 px apart), its span above it on the right. */\nvoid WidgetMyModule::drawHistory(Adafruit_SSD1306 &d)\n{\n    char b[8];\n    Ui::header(d, \"History\", PAGE_COUNT, PAGE_HISTORY);\n    Ui::bigValue(d, 14, tenthsText(b, sizeof(b), temperatureTenths()), \"C\");\n    d.setCursor(128 - Ui::ValueEnd - 6 * Ui::CharW, 40);\n    d.print(\"60 min\");\n    Ui::graph(d, 8, 50, 119, 13, 2, historyCount(), historyAt, nullptr);\n}\n#endif // DEVICE_DISPLAY_MODULE\n", "tpl-reg": "// In the module or main.cpp, after openknx.setup() (the display module exists then):\n#ifdef DEVICE_DISPLAY_MODULE\n#include \"DeviceDisplay.h\"\n#include \"WidgetMyModule.h\"\n#endif\n\n#ifdef DEVICE_DISPLAY_MODULE\n    // 10 s in the rotation. tryAddWidget() takes ownership and deletes the widget if there is no display.\n    if (!openknxDisplayModule.tryAddWidget(new WidgetMyModule(10000, WidgetFlags::DefaultWidget)))\n        openknx.logger.log(\"MyModule widget not registered (no display)\");\n#endif\n", "c-header": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\n// Widget page: title, page dots (3 pages, page 2), dotted line at y10.\nUi::header(d, \"Network\", 3, 1);\n// Menu or list: position \"3/12\" on the right instead of dots.\nUi::headerPos(d, \"Display\", 3, 12);", "c-row": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\nUi::row(d, 0, \"IP\", \"192.168.178.100\");              // y14, label on 5 columns, value after it\nUi::rowIcon(d, 1, Ui::kRowOk, \"Resets\", \"0\");         // 9x9 symbol, text, value right-aligned\nUi::rowIcon(d, 2, Ui::kRowWarn, \"Con rescues\", \"2\");\nUi::rowAt(d, 44, \"1.1.251\", \"10.0.0.21\", 9);          // 8 px data list at an explicit y", "c-card": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\n// Symbol callback: draws into x44..83 y1..27.\nstruct Sym { static void draw(Adafruit_SSD1306 &d) { d.drawRoundRect(52, 2, 24, 24, 3, WHITE); } };\nUi::statusCard(d, Sym::draw, Ui::kBadgeOk, \"Bus OK\", \"Load 412 B/s\");\nUi::pageDots(d, 4, 0);                                // card = page 1 of 4", "c-big": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\nUi::header(d, \"KNX Bus\");\nUi::bigValue(d, 14, \"412\", \"B/s\");                    // value size 2, unit size 1 behind it", "c-badge": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\nUi::badge(d, 14, 32, Ui::kBadgeOk);                   // filled circle r8, symbol 13x13 in black\nUi::badge(d, 39, 32, Ui::kBadgeError);\nUi::badge(d, 64, 32, Ui::kBadgeClock);\nUi::badge(d, 89, 32, Ui::kBadgeLock);\nUi::badge(d, 114, 32, Ui::kBadgeWarn);", "c-bar": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\nUi::bar(d, 0, 14, 128, Ui::NoValue);                  // frame only: no value yet\nUi::bar(d, 0, 28, 128, 650);                          // 65.0 %, fill 2 px inside", "c-toggle": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\n// Menu row value: \"On\" / \"Off\", the selected row shows \"< On >\"; right-aligned, ends at x125.\nconst char *v = Ui::toggleText(true, true);\nd.setCursor((int16_t)(128 - Ui::ValueEnd - (int16_t)strlen(v) * Ui::CharW), 24);\nd.print(v);", "c-keys": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\nconst int16_t w = Ui::keyHint(d, 0, 40, \"OK\", \"Open\");    // returns the width it used\nUi::keyHint(d, (int16_t)(w + 8), 40, \"<\", \"Close\");", "g-graph": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\n// Reader: sample i (0 = oldest) as 0..1000 permille, Ui::GraphGap for a missing value.\n// 60 samples, 2 px apart, newest at the right edge x126; baseline y63.\nUi::header(d, \"Bus load\");\nUi::graph(d, 8, 50, 119, 13, 2, 60, sampleAt, nullptr);", "c-text": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\nUi::printCentred(d, 14, \"ProgMode\", 2);              // centred, size 2, leaves size 1\nUi::printCut(d, 0, 34, \"A very long device name\", 14); // cut to 14 characters with \"...\"", "cat-1": "#include \"DisplayUi.h\"\n#include \"Icons/UiIcons.h\"\nnamespace Ui = OpenKNX::Ui;\n\n// Menu row value: \"On\" / \"Off\", the selected row shows \"< On >\"; right-aligned, ends at x125.\nconst char *v = Ui::toggleText(true, true);\nd.setCursor((int16_t)(128 - Ui::ValueEnd - (int16_t)strlen(v) * Ui::CharW), 24);\nd.print(v);", "cat-2": "// OFM-DeviceDisplay/src/Menu/Menu.cpp\n\n/** @brief Draws a 32x32 icon at half size with its top-left at (x0,y0); a pixel is lit if any of its 2x2 source pixels is, so 1-px lines survive. */\nvoid drawHalfIcon(Adafruit_SSD1306* d, int16_t x0, int16_t y0, const uint8_t* icon32)\n{\n    if (!icon32) return;\n    for (int16_t y = 0; y < 16; y++)\n        for (int16_t x = 0; x < 16; x++)\n        {\n            const uint8_t rows = pgm_read_byte(&icon32[y * 8 + (x >> 2)]) | pgm_read_byte(&icon32[y * 8 + 4 + (x >> 2)]);\n            if (rows & (0xC0 >> ((x & 3) << 1)))\n                d->drawPixel(static_cast<int16_t>(x0 + x), static_cast<int16_t>(y0 + y), WHITE);\n        }\n}\n\n// Carousel (handbook 2): header \"Menu  n/m\", the current icon 32x32 centred on (64,29), the neighbours at half size\n// centred on x16 / x112 with a triangle each, the name centred at y47 and the entry's valueProvider text at y56.\nvoid MenuWidget::drawCarousel(size_t count, size_t selVis, size_t prev, size_t next)\n{\n    Adafruit_SSD1306* d = _display->display;\n    OpenKNX::Ui::headerPos(*d, \"Menu\", static_cast<uint16_t>(selVis + 1), static_cast<uint16_t>(count));\n    if (_selectedIndex < _currentMenu.size())\n    {\n        const auto& item = _currentMenu[_selectedIndex];\n        if (const uint8_t* icon = OpenKNX::Ui::menuIcon32(item.label.c_str())) d->drawBitmap(48, 13, icon, 32, 32, WHITE);\n        if (prev < _currentMenu.size())\n        {\n            drawHalfIcon(d, 8, 21, OpenKNX::Ui::menuIcon32(_currentMenu[prev].label.c_str()));\n            d->fillTriangle(1, 29, 4, 26, 4, 32, WHITE);\n        }\n        if (next < _currentMenu.size())\n        {\n            drawHalfIcon(d, 104, 21, OpenKNX::Ui::menuIcon32(_currentMenu[next].label.c_str()));\n            d->fillTriangle(126, 29, 123, 26, 123, 32, WHITE);\n        }\n        OpenKNX::Ui::printCentred(*d, 47, item.label.c_str());\n        if (item.valueProvider)\n        {\n            const std::string info = item.valueProvider();\n            OpenKNX::Ui::printCentred(*d, 56, info.c_str());\n        }\n    }\n    _display->displayBuff();\n}", "cat-3": "// OFM-DeviceDisplay/src/Icons/UiIcons.h\n\n/**\n * @brief Returns the 32x32 carousel icon for a root menu label (exact match), nullptr if there is none.\n * \"Notify\" and \"SD card\" are listed only in builds with their module.\n */\ninline const uint8_t *menuIcon32(const char *label)\n{\n    struct Entry\n    {\n        const char *label;\n        const uint8_t *icon;\n    };\n    static constexpr Entry kTable[] = {\n        {\"System-Info\", kMenu32SystemInfo},\n        {\"Network\", kMenu32Network},\n        {\"Display\", kMenu32Display},\n        {\"Widgets\", kMenu32Widgets},\n        {\"System\", kMenu32System},\n        {\"Screenshot\", kMenu32Screenshot},\n        {\"Home keys\", kMenu32HomeKeys},\n#ifdef OPENKNX_NOTIFY\n        {\"Notify\", kMenu32Notify},\n#endif\n#if defined(OPENKNX_SDCARD) || defined(OPENKNX_SD_CARD_MODULE_ENABLE)\n        {\"SD card\", kMenu32SdCard},\n#endif\n        {\"< Exit\", kMenu32Exit},\n        {\"About\", kMenu32About},\n    };\n    if (label == nullptr) return nullptr;\n    for (const Entry &e : kTable)\n        if (strcmp(label, e.label) == 0) return e.icon;\n    return nullptr;\n}", "cat-4": "// OFM-DeviceDisplay/src/Menu/Menu.cpp\n\n/** @brief List scrollbar: dots at x127 every second row y12..60, thumb x126..127 placed by the first visible row. */\nvoid drawScrollbar(Adafruit_SSD1306* d, size_t first, size_t count)\n{\n    for (int16_t py = ListTop; py < ListTop + ListRows * ListPitch; py += 2)\n        d->drawPixel(127, py, WHITE);\n    const int16_t track = ListRows * ListPitch;\n    int16_t thumb = static_cast<int16_t>(track * ListRows / static_cast<int32_t>(count));\n    if (thumb < 4) thumb = 4;\n    const int16_t ty = static_cast<int16_t>(ListTop + static_cast<int32_t>(track - thumb) * static_cast<int32_t>(first) / static_cast<int32_t>(count - ListRows));\n    d->fillRect(126, ty, 2, thumb, WHITE);\n}\n\nvoid MenuWidget::drawMenu()\n{\n    if (!_display || !_display->display) return;\n    Adafruit_SSD1306* d = _display->display;\n    OpenKNX::Ui::begin(*d); // T7: every menu and editor frame starts from size 1, WHITE, no wrap\n\n    // Editor sub-modes draw their own full-screen editor.\n    if (_mode == MenuMode::IpEdit)\n    {\n        drawIpEditor();\n        return;\n    }\n    if (_mode == MenuMode::Reorder)\n    {\n        drawReorder();\n        return;\n    }\n    if (_mode == MenuMode::RadioSelect)\n    {\n        drawRadioSelect();\n        return;\n    }\n    if (_mode == MenuMode::Slider)\n    {\n        drawSlider();\n        return;\n    }\n    if (_mode == MenuMode::TextEdit)\n    {\n        drawTextEditor();\n        return;\n    }\n    if (_mode == MenuMode::ConfirmDialog)\n    {\n        drawConfirmDialog();\n        return;\n    }\n    if (_mode == MenuMode::NumberEdit)\n    {\n        drawNumberEditor();\n        return;\n    }\n\n    d->clearDisplay();\n\n    if (_infoOverlayActive && _overlayDrawFunction)\n    {\n        _overlayDrawFunction(); // We draw the info overlay\n        return;                 // Skip the rest of the menu drawing\n    }\n\n    // Visible entries (visibleIf + devOnly): count, position of the selection, its visible neighbours.\n    constexpr size_t NONE = static_cast<size_t>(-1);\n    size_t count = 0, selVis = 0, prev = NONE, next = NONE;\n    for (size_t i = 0; i < _currentMenu.size(); ++i)\n    {\n        if (!isItemVisible(_currentMenu[i])) continue;\n        if (i < _selectedIndex)\n            prev = i;\n        else if (i == _selectedIndex)\n            selVis = count;\n        else if (next == NONE)\n            next = i;\n        ++count;\n    }\n    if (count == 0)\n    {\n        _display->displayBuff();\n        return;\n    }\n\n    // Icon main menu: at the root, the categories as a carousel instead of a text list.\n    if (iconGridActive())\n    {\n        drawCarousel(count, selVis, prev, next);\n        return;\n    }\n\n    // Header: \"Menu\" at the root, else the label of the entry that opened this level.\n    const char* title = \"Menu\";\n    if (!_menuStack.empty() && !_selectedIndexStack.empty() && _selectedIndexStack.back() < _menuStack.back().size())\n        title = _menuStack.back()[_selectedIndexStack.back()].label.c_str();\n    OpenKNX::Ui::headerPos(*d, title, static_cast<uint16_t>(selVis + 1), static_cast<uint16_t>(count));\n\n    const bool scrollbar = count > static_cast<size_t>(ListRows);\n    const int16_t rowW = scrollbar ? 124 : static_cast<int16_t>(_screenWidth); // selection fill x0..rowW-1\n    const int16_t valueEnd = scrollbar ? 124 : 126;                             // value cells end at x123 / x125\n    const size_t startVis = (selVis >= static_cast<size_t>(ListRows)) ? selVis - (ListRows - 1) : 0;\n\n    size_t v = 0;\n    for (size_t i = 0; i < _currentMenu.size() && v < startVis + ListRows; ++i)\n    {\n        const auto& item = _currentMenu[i];\n        if (!isItemVisible(item)) continue;\n        if (v++ < startVis) continue;\n\n        const int16_t y = static_cast<int16_t>(ListTop + (v - 1 - startVis) * ListPitch);\n        const bool isSelected = (i == _selectedIndex);\n        if (isSelected) d->fillRect(0, y, rowW, ListPitch, WHITE);\n        d->setTextColor(isSelected ? BLACK : WHITE);\n\n        // Value forms: toggles \"On\"/\"Off\" (\"< On >\" selected); selected plain Dropdown \"< v >\", picker/slider\n        // Dropdown \"v >\"; selected DHCP-locked IP row \"auto (DHCP)\". The value is never cut, only the label.\n        char wrapped[40];\n        std::string valueText;\n        const char* value = nullptr;\n        if (item.type == MenuConfig::MenuElementType::Checkbox || item.type == MenuConfig::MenuElementType::ProgToggle)\n        {\n            const bool on = (item.type == MenuConfig::MenuElementType::ProgToggle) ? knx.progMode() : item.defaultValue.getBool();\n            value = OpenKNX::Ui::toggleText(on, isSelected);\n        }\n        else if (isSelected && isDhcpLocked(item))\n            value = \"auto (DHCP)\";\n        else\n        {\n            valueText = itemValueText(item);\n            value = valueText.c_str();\n            if (isSelected && !valueText.empty() && item.type == MenuConfig::MenuElementType::Dropdown)\n            {\n                snprintf(wrapped, sizeof(wrapped), (item.radioList || item.slider) ? \"%s >\" : \"< %s >\", value);\n                value = wrapped;\n            }\n        }\n\n        int16_t labelEnd = valueEnd; // label cells end at least 2 px before the value, else before valueEnd\n        if (value && *value)\n        {\n            int16_t vx = static_cast<int16_t>(valueEnd - static_cast<int16_t>(strlen(value)) * CharW);\n            if (vx < 0) vx = 0;\n            d->setCursor(vx, static_cast<int16_t>(y + 1));\n            d->print(value);\n            labelEnd = static_cast<int16_t>(vx - 2);\n        }\n        OpenKNX::Ui::printCut(*d, 2, static_cast<int16_t>(y + 1), item.label.c_str(), static_cast<int16_t>((labelEnd - 2) / CharW));\n    }\n\n    if (scrollbar) drawScrollbar(d, startVis, count);\n    d->setTextColor(WHITE);\n    _display->displayBuff();\n}", "cat-5": "// OFM-DeviceDisplay/src/Menu/Menu.cpp\n\n/** @brief List scrollbar: dots at x127 every second row y12..60, thumb x126..127 placed by the first visible row. */\nvoid drawScrollbar(Adafruit_SSD1306* d, size_t first, size_t count)\n{\n    for (int16_t py = ListTop; py < ListTop + ListRows * ListPitch; py += 2)\n        d->drawPixel(127, py, WHITE);\n    const int16_t track = ListRows * ListPitch;\n    int16_t thumb = static_cast<int16_t>(track * ListRows / static_cast<int32_t>(count));\n    if (thumb < 4) thumb = 4;\n    const int16_t ty = static_cast<int16_t>(ListTop + static_cast<int32_t>(track - thumb) * static_cast<int32_t>(first) / static_cast<int32_t>(count - ListRows));\n    d->fillRect(126, ty, 2, thumb, WHITE);\n}\n\nvoid MenuWidget::drawMenu()\n{\n    if (!_display || !_display->display) return;\n    Adafruit_SSD1306* d = _display->display;\n    OpenKNX::Ui::begin(*d); // T7: every menu and editor frame starts from size 1, WHITE, no wrap\n\n    // Editor sub-modes draw their own full-screen editor.\n    if (_mode == MenuMode::IpEdit)\n    {\n        drawIpEditor();\n        return;\n    }\n    if (_mode == MenuMode::Reorder)\n    {\n        drawReorder();\n        return;\n    }\n    if (_mode == MenuMode::RadioSelect)\n    {\n        drawRadioSelect();\n        return;\n    }\n    if (_mode == MenuMode::Slider)\n    {\n        drawSlider();\n        return;\n    }\n    if (_mode == MenuMode::TextEdit)\n    {\n        drawTextEditor();\n        return;\n    }\n    if (_mode == MenuMode::ConfirmDialog)\n    {\n        drawConfirmDialog();\n        return;\n    }\n    if (_mode == MenuMode::NumberEdit)\n    {\n        drawNumberEditor();\n        return;\n    }\n\n    d->clearDisplay();\n\n    if (_infoOverlayActive && _overlayDrawFunction)\n    {\n        _overlayDrawFunction(); // We draw the info overlay\n        return;                 // Skip the rest of the menu drawing\n    }\n\n    // Visible entries (visibleIf + devOnly): count, position of the selection, its visible neighbours.\n    constexpr size_t NONE = static_cast<size_t>(-1);\n    size_t count = 0, selVis = 0, prev = NONE, next = NONE;\n    for (size_t i = 0; i < _currentMenu.size(); ++i)\n    {\n        if (!isItemVisible(_currentMenu[i])) continue;\n        if (i < _selectedIndex)\n            prev = i;\n        else if (i == _selectedIndex)\n            selVis = count;\n        else if (next == NONE)\n            next = i;\n        ++count;\n    }\n    if (count == 0)\n    {\n        _display->displayBuff();\n        return;\n    }\n\n    // Icon main menu: at the root, the categories as a carousel instead of a text list.\n    if (iconGridActive())\n    {\n        drawCarousel(count, selVis, prev, next);\n        return;\n    }\n\n    // Header: \"Menu\" at the root, else the label of the entry that opened this level.\n    const char* title = \"Menu\";\n    if (!_menuStack.empty() && !_selectedIndexStack.empty() && _selectedIndexStack.back() < _menuStack.back().size())\n        title = _menuStack.back()[_selectedIndexStack.back()].label.c_str();\n    OpenKNX::Ui::headerPos(*d, title, static_cast<uint16_t>(selVis + 1), static_cast<uint16_t>(count));\n\n    const bool scrollbar = count > static_cast<size_t>(ListRows);\n    const int16_t rowW = scrollbar ? 124 : static_cast<int16_t>(_screenWidth); // selection fill x0..rowW-1\n    const int16_t valueEnd = scrollbar ? 124 : 126;                             // value cells end at x123 / x125\n    const size_t startVis = (selVis >= static_cast<size_t>(ListRows)) ? selVis - (ListRows - 1) : 0;\n\n    size_t v = 0;\n    for (size_t i = 0; i < _currentMenu.size() && v < startVis + ListRows; ++i)\n    {\n        const auto& item = _currentMenu[i];\n        if (!isItemVisible(item)) continue;\n        if (v++ < startVis) continue;\n\n        const int16_t y = static_cast<int16_t>(ListTop + (v - 1 - startVis) * ListPitch);\n        const bool isSelected = (i == _selectedIndex);\n        if (isSelected) d->fillRect(0, y, rowW, ListPitch, WHITE);\n        d->setTextColor(isSelected ? BLACK : WHITE);\n\n        // Value forms: toggles \"On\"/\"Off\" (\"< On >\" selected); selected plain Dropdown \"< v >\", picker/slider\n        // Dropdown \"v >\"; selected DHCP-locked IP row \"auto (DHCP)\". The value is never cut, only the label.\n        char wrapped[40];\n        std::string valueText;\n        const char* value = nullptr;\n        if (item.type == MenuConfig::MenuElementType::Checkbox || item.type == MenuConfig::MenuElementType::ProgToggle)\n        {\n            const bool on = (item.type == MenuConfig::MenuElementType::ProgToggle) ? knx.progMode() : item.defaultValue.getBool();\n            value = OpenKNX::Ui::toggleText(on, isSelected);\n        }\n        else if (isSelected && isDhcpLocked(item))\n            value = \"auto (DHCP)\";\n        else\n        {\n            valueText = itemValueText(item);\n            value = valueText.c_str();\n            if (isSelected && !valueText.empty() && item.type == MenuConfig::MenuElementType::Dropdown)\n            {\n                snprintf(wrapped, sizeof(wrapped), (item.radioList || item.slider) ? \"%s >\" : \"< %s >\", value);\n                value = wrapped;\n            }\n        }\n\n        int16_t labelEnd = valueEnd; // label cells end at least 2 px before the value, else before valueEnd\n        if (value && *value)\n        {\n            int16_t vx = static_cast<int16_t>(valueEnd - static_cast<int16_t>(strlen(value)) * CharW);\n            if (vx < 0) vx = 0;\n            d->setCursor(vx, static_cast<int16_t>(y + 1));\n            d->print(value);\n            labelEnd = static_cast<int16_t>(vx - 2);\n        }\n        OpenKNX::Ui::printCut(*d, 2, static_cast<int16_t>(y + 1), item.label.c_str(), static_cast<int16_t>((labelEnd - 2) / CharW));\n    }\n\n    if (scrollbar) drawScrollbar(d, startVis, count);\n    d->setTextColor(WHITE);\n    _display->displayBuff();\n}", "cat-6": "// OFM-DeviceDisplay/src/Menu/Menu.cpp\n\n// Render the radio picker: header \"label  n/m\" + 5 option rows from y12 in 10 px; the highlighted row is inverted\n// with a filled bullet, others hollow. More than 5 options add the list scrollbar.\nvoid MenuWidget::drawRadioSelect()\n{\n    if (!_display || !_display->display) return;\n    if (_radioIndex >= _currentMenu.size())\n    {\n        leaveEditor();\n        return;\n    }\n    Adafruit_SSD1306* d = _display->display;\n    const auto& item = _currentMenu[_radioIndex];\n    const size_t count = item.dropdownOptions.size();\n\n    d->clearDisplay();\n    OpenKNX::Ui::headerPos(*d, item.label.c_str(), static_cast<uint16_t>(_radioSel + 1), static_cast<uint16_t>(count));\n\n    const uint8_t visibleRows = ListRows;\n    if (visibleRows == 0 || count == 0)\n    {\n        _display->displayBuff();\n        return;\n    }\n\n    // Keep the highlighted option in view (scroll offset).\n    if (_radioSel < _radioTop) _radioTop = _radioSel;\n    else if (_radioSel >= _radioTop + visibleRows)\n        _radioTop = _radioSel - visibleRows + 1;\n    if (count >= visibleRows && _radioTop + visibleRows > count) _radioTop = count - visibleRows;\n\n    const bool scrollbar = count > visibleRows;\n    const int16_t rowW = scrollbar ? 124 : static_cast<int16_t>(_screenWidth); // selection fill and text end before rowW\n    for (size_t row = 0; row < visibleRows && (_radioTop + row) < count; ++row)\n    {\n        const size_t idx = _radioTop + row;\n        const int16_t y = static_cast<int16_t>(ListTop + row * ListPitch);\n        const bool sel = (idx == _radioSel);\n        const uint16_t fg = sel ? BLACK : WHITE;\n\n        if (sel) d->fillRect(0, y, rowW, ListPitch, WHITE);\n\n        // Radio bullet: filled dot when selected, hollow ring otherwise.\n        const int16_t cx = 6, cy = static_cast<int16_t>(y + 4);\n        d->drawCircle(cx, cy, 3, fg);\n        if (sel) d->fillCircle(cx, cy, 1, fg);\n\n        d->setTextColor(fg);\n        OpenKNX::Ui::printCut(*d, 14, static_cast<int16_t>(y + 1), item.dropdownOptions[idx].c_str(), static_cast<int16_t>((rowW - 14) / CharW));\n    }\n    d->setTextColor(WHITE);\n    if (scrollbar) drawScrollbar(d, _radioTop, count);\n\n    _display->displayBuff();\n}\n\n// Render: title + wrapped message + [Nein] [Ja] (selected filled).\nvoid MenuWidget::drawConfirmDialog()\n{\n    if (!_display || !_display->display) return;\n    auto* d = _display->display;\n\n    d->clearDisplay();\n    OpenKNX::Ui::header(*d, _confirmTitle.c_str());\n    d->setTextColor(WHITE, BLACK);\n\n    // Message word-wrapped to full-width lines (6px font), up to 3 lines at y=14/23/32. Break at the\n    // last space that fits so words are not split mid-letter; fall back to a hard cut for a word that\n    // is longer than one line.\n    const size_t perLine = (_screenWidth > 12) ? (size_t)((_screenWidth - 4) / 6) : 20;\n    size_t pos = 0;\n    for (int16_t my = 14; pos < _confirmMessage.size() && my <= 32; my = (int16_t)(my + 9))\n    {\n        size_t len = _confirmMessage.size() - pos;\n        if (len > perLine)\n        {\n            len = perLine; // hard cut fallback\n            const size_t sp = _confirmMessage.rfind(' ', pos + perLine);\n            if (sp != std::string::npos && sp > pos)\n                len = sp - pos; // break at the last space within the line\n        }\n        d->setCursor(2, my);\n        d->write(reinterpret_cast<const uint8_t*>(_confirmMessage.c_str() + pos), len);\n        pos += len;\n        while (pos < _confirmMessage.size() && _confirmMessage[pos] == ' ')\n            pos++; // swallow the break space(s)\n    }\n\n    // Buttons [Nein] [Ja]; the selected one is filled, the other outlined.\n    static const char* const OPTS[2] = {\"No\", \"Yes\"};\n    const int16_t by = 46, bh = 14, bw = 50;\n    for (uint8_t i = 0; i < 2; i++)\n    {\n        const int16_t bx = (i == 0) ? 8 : (int16_t)(_screenWidth - bw - 8);\n        if (i == _confirmSel)\n        {\n            d->fillRect(bx, by, bw, bh, WHITE);\n            d->setTextColor(BLACK);\n        }\n        else\n        {\n            d->drawRect(bx, by, bw, bh, WHITE);\n            d->setTextColor(WHITE);\n        }\n        const int16_t tw = (int16_t)(strlen(OPTS[i]) * 6);\n        d->setCursor((int16_t)(bx + (bw - tw) / 2), (int16_t)(by + 4));\n        d->print(OPTS[i]);\n        d->setTextColor(WHITE, BLACK);\n    }\n\n    _display->displayBuff();\n}", "cat-7": "// OFM-DeviceDisplay/src/Menu/Menu.cpp\n\n// Render the text editor: header \"label  n/max\", the string at size 2 windowed so the cursor stays\n// visible (active cell blinks), the charset neighbours at y34, the four groups at y46 and the key hint at y56.\nvoid MenuWidget::drawTextEditor()\n{\n    if (!_display || !_display->display) return;\n    auto* d = _display->display;\n\n    d->clearDisplay();\n    const char* label = (_textEditIndex < _currentMenu.size()) ? _currentMenu[_textEditIndex].label.c_str() : \"Text\";\n    // Count what OK would store: trailing spaces (the seeded or grown empty cells) are trimmed on commit.\n    const size_t last = _textEdit.find_last_not_of(' ');\n    OpenKNX::Ui::headerPos(*d, label, static_cast<uint16_t>(last == std::string::npos ? 0 : last + 1), textMax());\n\n    // Characters at size 2 from x4, y14; 10 cells of 12 px.\n    d->setTextSize(2);\n    const int16_t cellW = 12;\n    const uint8_t visible = 10;\n    const uint8_t start = (_textCursor >= visible) ? static_cast<uint8_t>(_textCursor - visible + 1) : 0;\n    int16_t cx = 4;\n    for (uint8_t i = start; i < _textEdit.size() && i < start + visible; ++i, cx = static_cast<int16_t>(cx + cellW))\n    {\n        if (i == _textCursor)\n        {\n            if (!_editBlinkOn) continue; // \"off\" phase: leave the active cell blank (blink)\n            d->fillRect(static_cast<int16_t>(cx - 1), 13, 13, 17, WHITE);\n            d->setTextColor(BLACK);\n        }\n        d->setCursor(cx, 14);\n        d->write(static_cast<uint8_t>(_textEdit[i]));\n        d->setTextColor(WHITE);\n    }\n    d->setTextSize(1);\n\n    // Neighbour strip: 4 accepted characters either side of the active one, the active one inverted; space as '_'.\n    if (_textCursor < _textEdit.size())\n    {\n        const char active = _textEdit[_textCursor];\n        const int16_t idx = charIndex(active);\n        const char* allowed = textAllowed();\n        d->fillRect(58, 32, 11, 11, WHITE);\n        d->setTextColor(BLACK);\n        d->setCursor(61, 34);\n        d->write(static_cast<uint8_t>(active == ' ' ? '_' : active));\n        d->setTextColor(WHITE);\n        if (idx >= 0)\n        {\n            int16_t left = idx, right = idx;\n            for (int16_t n = 1; n <= 4; n++)\n            {\n                left = charStep(left, -1, allowed);\n                right = charStep(right, 1, allowed);\n                const char lc = kCharset[left], rc = kCharset[right];\n                d->setCursor(static_cast<int16_t>(61 - 12 * n), 34);\n                d->write(static_cast<uint8_t>(lc == ' ' ? '_' : lc));\n                d->setCursor(static_cast<int16_t>(61 + 12 * n), 34);\n                d->write(static_cast<uint8_t>(rc == ' ' ? '_' : rc));\n            }\n        }\n\n        // Groups; the one holding the active character inverted.\n        const int8_t activeGroup = (idx >= 0) ? static_cast<int8_t>(charGroup(idx)) : -1;\n        for (uint8_t g = 0; g < 4; g++)\n        {\n            const int16_t gx = static_cast<int16_t>(10 + 30 * g);\n            if (g == activeGroup)\n            {\n                d->fillRoundRect(static_cast<int16_t>(gx - 3), 45, 23, 10, 2, WHITE);\n                d->setTextColor(BLACK);\n            }\n            d->setCursor(gx, 46);\n            d->print(kGroupName[g]);\n            d->setTextColor(WHITE);\n        }\n    }\n\n    d->setCursor(0, 56);\n    d->print(\"OK=done ^v hold=group\");\n\n    _display->displayBuff();\n}", "cat-8": "// OFM-DeviceDisplay/src/Widgets/ProgMode.cpp\n\nvoid WidgetProgMode::draw()\n{\n    _redraw = false;\n    _drawnPa = openknx.info.individualAddress();\n\n    Adafruit_SSD1306 &d = *_display->display;\n    OpenKNX::Ui::begin(d);\n    d.clearDisplay();\n    OpenKNX::Ui::header(d, \"Prog-Mode\", 1, 0);\n\n    // Blink phase on: white box 4 px around the text, text in BLACK. x is the printCentred() position.\n    static const char kWord[] = \"ProgMode\";\n    if (_showProgMode)\n    {\n        constexpr int16_t textW = (sizeof(kWord) - 1) * OpenKNX::Ui::CharW * 2;\n        const int16_t x = static_cast<int16_t>((d.width() - textW + 2) / 2);\n        d.fillRect(static_cast<int16_t>(x - 4), 13, textW + 6, 18, WHITE);\n        d.setTextColor(BLACK);\n    }\n    OpenKNX::Ui::printCentred(d, 14, kWord, 2);\n    d.setTextColor(WHITE);\n\n    char pa[14]; // \"PA 15.15.255\"\n    snprintf(pa, sizeof(pa), \"PA %u.%u.%u\", static_cast<unsigned>(_drawnPa >> 12), static_cast<unsigned>((_drawnPa >> 8) & 0x0F),\n             static_cast<unsigned>(_drawnPa & 0xFF));\n    OpenKNX::Ui::printCentred(d, 34, pa);\n    OpenKNX::Ui::printCentred(d, 44, \"Ready to program\");\n    OpenKNX::Ui::printCentred(d, 54, \"Hold OK = exit\");\n    _display->displayBuff();\n}", "cat-9": "// OFM-DeviceDisplay/src/Widgets/OTAUpdate.cpp\n\nvoid WidgetOTA::draw()\n{\n    _redraw = false;\n\n    Adafruit_SSD1306 &d = *_display->display;\n    OpenKNX::Ui::begin(d);\n    d.clearDisplay();\n    OpenKNX::Ui::header(d, \"OTA Update\", 1, 0);\n    // Activity square in the top-right corner: the manager overlay draws only on a DefaultWidget.\n    if (_blinkOn) d.fillRect(120, 0, 6, 6, WHITE);\n\n    char buf[6]; // \"100 %\"\n    snprintf(buf, sizeof(buf), \"%u %%\", static_cast<unsigned>(_percent));\n    OpenKNX::Ui::printCentred(d, 14, buf, 2);\n    OpenKNX::Ui::bar(d, 0, 32, d.width(), static_cast<uint16_t>(_percent * 10));\n    OpenKNX::Ui::printCentred(d, 54, \"Keep power on\");\n    _display->displayBuff();\n}", "cat-10": "// OFM-DeviceDisplay/src/Widgets/GestureOverlay.cpp\n\nconst char *WidgetGestureOverlay::titleForAction(GestureAction action) const\n{\n    // Header: what holding does; Exit/Resume when the state is already on.\n    switch (action)\n    {\n        case GestureAction::Pause:\n            return _pauseActive ? \"Resume\" : \"Pause\";\n        case GestureAction::Reboot:\n            return \"Restart\";\n        case GestureAction::ProgMode:\n            return _progActive ? \"Exit\" : \"Activate\";\n        case GestureAction::DisplayOff:\n            return \"Turn off\";\n        case GestureAction::Screenshot:\n            return \"Capture\";\n        default:\n            return \"Action\";\n    }\n}\n\nconst char *WidgetGestureOverlay::labelForAction(GestureAction action) const\n{\n    // Size-2 line: what the action works on (10 characters fit).\n    switch (action)\n    {\n        case GestureAction::Pause:\n            return \"Rotation\";\n        case GestureAction::Reboot:\n            return \"Device\";\n        case GestureAction::ProgMode:\n            return \"ProgMode\";\n        case GestureAction::DisplayOff:\n            return \"Display\";\n        case GestureAction::Screenshot:\n            return \"Screen\";\n        default:\n            return \"\";\n    }\n}\n\nvoid WidgetGestureOverlay::draw(uint16_t fill)\n{\n    Adafruit_SSD1306 &d = *_display->display;\n    OpenKNX::Ui::begin(d);\n    d.clearDisplay();\n    OpenKNX::Ui::header(d, titleForAction(_lastAction), 1, 0);\n    OpenKNX::Ui::printCentred(d, 14, labelForAction(_lastAction), 2);\n    OpenKNX::Ui::bar(d, 0, 32, d.width(), fill);\n\n    char left[8]; // \"3.0 s\"\n    snprintf(left, sizeof(left), \"%u.%u s\", static_cast<unsigned>(_lastTenths / 10), static_cast<unsigned>(_lastTenths % 10));\n    OpenKNX::Ui::printCentred(d, 44, left);\n    // Hold: releasing early aborts; Auto (menu-triggered): LEFT aborts.\n    OpenKNX::Ui::printCentred(d, 54, _mode == GestureOverlayMode::Hold ? \"Release = cancel\" : \"< Cancel\");\n    _display->displayBuff();\n}", "cat-11": "// OAM-IP-Interface/src/DisplayWidgets/WidgetIPInterface.cpp\n\n/** @brief Card symbol: IP and TP boxes with arrows both ways, in x44..83 y1..27 (s-ipif). */\nstatic void drawIpTpSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawRoundRect(44, 3, 17, 22, 2, WHITE);\n    d.setCursor(47, 10);\n    d.print(\"IP\");\n    d.drawRoundRect(67, 3, 17, 22, 2, WHITE);\n    d.setCursor(70, 10);\n    d.print(\"TP\");\n    d.drawFastHLine(61, 9, 6, WHITE);\n    d.fillTriangle(66, 9, 64, 7, 64, 11, WHITE);\n    d.drawFastHLine(61, 17, 6, WHITE);\n    d.fillTriangle(61, 17, 63, 15, 63, 19, WHITE);\n}\n\nvoid WidgetIPInterface::drawCard(Adafruit_SSD1306 &d)\n{\n    const uint8_t *badge = Ui::kBadgeError;\n    const char *word = \"No bus\";\n    const char *detail = \"No TP link\";\n    char b[24];\n\n    TpUartDataLinkLayer *dll = knx.bau().getDataLinkLayer();\n    if (!openknxNetwork.established())\n    {\n        word = \"No LAN\";\n        detail = \"Check cable\";\n    }\n    else if (dll)\n    {\n        switch (dll->getTPUart().getBcuState())\n        {\n            case TPUart::BCU_DISCONNECTED:\n                detail = \"Check KNX line\";\n                break;\n            case TPUart::BCU_UNINITIALIZED:\n                // Only the first 30 s after boot count as start-up; later an uninitialised BCU means no bus.\n                if (uptime() >= 30) // wrap-safe seconds since boot\n                {\n                    detail = \"Check KNX line\";\n                    break;\n                }\n                badge = Ui::kBadgeClock;\n                word = \"Starting\";\n                detail = \"TP starting\";\n                break;\n            case TPUart::BCU_BUSMONITOR:\n                badge = nullptr;\n                word = \"Busmon\";\n                detail = \"Monitor active\";\n                break;\n            default:\n            {\n                // Bus power loss: bus-powered chip after ~3 unanswered probes, external NCN via VBUS; BCU state lags.\n                if (!dll->getTPUart().busOperational())\n                {\n                    detail = \"Check KNX line\";\n                    break;\n                }\n                IpTunnelServer &ts = knx.bau().getIpTunnelServer();\n                const uint8_t n = ts.tunnelCount();\n                const std::string load = humanBytes(openknx.busLoad.currentBytesPerSec());\n                const KnxIpTunnelConnection *t = n == 1 ? ts.tunnelAt(0) : nullptr;\n                if (t)\n                {\n                    // One client: who it is; the load only while both fit the line.\n                    char ip[16];\n                    formatIp(t->IpAddress, ip, sizeof(ip));\n                    if (snprintf(b, sizeof(b), \"%s  %s/s\", ip, load.c_str()) > 21)\n                        snprintf(b, sizeof(b), \"%s\", ip);\n                }\n                else\n                    snprintf(b, sizeof(b), \"%u %s  %s/s\", (unsigned)n, n == 1 ? \"tunnel\" : \"tunnels\", load.c_str());\n                badge = Ui::kBadgeOk;\n                word = n ? \"Active\" : \"Ready\";\n                detail = b;\n                break;\n            }\n        }\n    }\n\n    Ui::statusCard(d, drawIpTpSymbol, badge, word, detail);\n    Ui::pageDots(d, PAGE_COUNT, PAGE_CARD);\n}", "cat-12": "// OAM-IP-Interface/src/DisplayWidgets/WidgetIPInterface.cpp\n\n/** @brief Dotted IPv4 into buf without the heap String of IPAddress::toString(). */\nstatic const char *formatAddr(const IPAddress &ip, char *buf, size_t n)\n{\n    snprintf(buf, n, \"%u.%u.%u.%u\", (unsigned)ip[0], (unsigned)ip[1], (unsigned)ip[2], (unsigned)ip[3]);\n    return buf;\n}\n\nvoid WidgetIPInterface::drawOverview(Adafruit_SSD1306 &d)\n{\n    // The assignment method sits in the title, so a 15-character IP fits its row.\n    Ui::header(d, openknxNetwork.localUsesStaticIp() ? \"Overview FIX\" : \"Overview DHCP\", PAGE_COUNT, PAGE_OVERVIEW);\n\n    if (!openknxNetwork.established())\n    {\n        drawDisconnected(d);\n        return;\n    }\n\n    static const struct\n    {\n        uint8_t row;\n        const char *label;\n        IPAddress (NetworkModule::*get)();\n    } kAddr[] = {{0, \"IP\", &NetworkModule::localIP}, {1, \"GW\", &NetworkModule::gatewayIP},\n                 {2, \"DNS\", &NetworkModule::nameServerIP}, {4, \"Mask\", &NetworkModule::subnetMask}};\n    char b[16];\n    for (const auto &a : kAddr)\n        Ui::row(d, a.row, a.label, formatAddr((openknxNetwork.*a.get)(), b, sizeof(b)));\n    Ui::row(d, 3, \"PA\", openknx.info.humanIndividualAddress().c_str());\n}", "cat-13": "// OAM-IP-Interface/src/DisplayWidgets/WidgetIPInterface.cpp\n\nstatic void tunnelText(const KnxIpTunnelConnection &t, int16_t lineChars, TunnelText &out)\n{\n    snprintf(out.pa, sizeof(out.pa), \"%u.%u.%u\", (unsigned)((t.IndividualAddress >> 12) & 0x0F),\n             (unsigned)((t.IndividualAddress >> 8) & 0x0F), (unsigned)(t.IndividualAddress & 0xFF));\n    formatIp(t.IpAddress, out.ip, sizeof(out.ip));\n    const size_t paLen = strlen(out.pa);\n    out.col = paLen + 1 > PA_COLS ? (uint8_t)(paLen + 1) : PA_COLS;\n    out.rows = (int16_t)(out.col + strlen(out.ip)) <= lineChars ? 1 : 2;\n}\n\n/**\n * @brief Lays the tunnel list (tunnels, then the busmonitor row) out in pages of LIST_ROWS rows.\n * An entry never splits across pages. Draws page `show` when d is set; returns the page count.\n */\nstatic uint8_t tunnelList(Adafruit_SSD1306 *d, IpTunnelServer &ts, uint8_t cnt, bool bm, int16_t lineChars, uint8_t show)\n{\n    TunnelText tt;\n    uint8_t page = 0, used = 0;\n    const uint8_t items = (uint8_t)(cnt + (bm ? 1 : 0));\n    for (uint8_t i = 0; i < items; i++)\n    {\n        const KnxIpTunnelConnection *t = i < cnt ? ts.tunnelAt(i) : nullptr;\n        if (i < cnt && !t) continue;\n        uint8_t h = 1;\n        if (t)\n        {\n            tunnelText(*t, lineChars, tt);\n            h = tt.rows;\n        }\n        if (used + h > LIST_ROWS)\n        {\n            page++;\n            used = 0;\n        }\n        if (d && page == show)\n        {\n            const int16_t y = (int16_t)(LIST_Y + used * Ui::PitchDense);\n            if (!t)\n                Ui::rowAt(*d, y, \"BM busmonitor\", nullptr);\n            else if (tt.rows == 1)\n                Ui::rowAt(*d, y, tt.pa, tt.ip, tt.col);\n            else\n            {\n                Ui::rowAt(*d, y, tt.pa, nullptr);\n                Ui::rowAt(*d, (int16_t)(y + Ui::PitchDense), nullptr, tt.ip, PA_COLS);\n            }\n        }\n        used += h;\n    }\n    return (uint8_t)(page + 1);\n}\n\nvoid WidgetIPInterface::drawTunnels(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Tunnels\", PAGE_COUNT, PAGE_TUNNELS);\n\n    IpTunnelServer &ts = knx.bau().getIpTunnelServer();\n    const uint8_t cnt = ts.tunnelCount();\n    const uint8_t mx = ts.tunnelMax();\n#ifdef OPENKNX_HW_BUSMON\n    const bool bm = ts.busMonitorActive();\n#else\n    const bool bm = false;\n#endif\n\n    char b[24];\n    snprintf(b, sizeof(b), \"%u of %u in use%s\", (unsigned)cnt, (unsigned)mx, bm ? \" +BM\" : \"\");\n    Ui::row(d, 0, b, nullptr);\n\n    // Slots 7x6 at y24: filled = open tunnel, checkerboard = busmonitor, frame = free.\n    const int16_t W = d.width();\n    const int16_t pitch = mx ? (int16_t)(W / mx) : 0;\n    if (pitch >= 2)\n    {\n        for (uint8_t i = 0; i < mx; i++)\n        {\n            const int16_t x = i * pitch;\n            if (i < cnt)\n                d.fillRect(x, 24, pitch - 1, 6, WHITE);\n            else if (bm && i == cnt)\n            {\n                for (int16_t py = 24; py < 30; py++)\n                    for (int16_t px = x + ((x + py) & 1); px < x + pitch - 1; px += 2)\n                        d.drawPixel(px, py, WHITE);\n            }\n            else\n                d.drawRect(x, 24, pitch - 1, 6, WHITE);\n        }\n    }\n\n    if (cnt == 0 && !bm)\n    {\n        Ui::rowAt(d, LIST_Y, \"no client connected\", nullptr);\n        return;\n    }\n\n    // A list longer than LIST_ROWS rows pages every LIST_PAGE_MS.\n    const int16_t lineChars = (int16_t)((W - Ui::ValueEnd) / Ui::CharW);\n    const uint8_t pages = tunnelList(nullptr, ts, cnt, bm, lineChars, 0);\n    tunnelList(&d, ts, cnt, bm, lineChars, pages > 1 ? (uint8_t)((millis() / LIST_PAGE_MS) % pages) : 0);\n}", "cat-14": "// OAM-IP-Interface/src/DisplayWidgets/WidgetIPInterface.cpp\n\n/** @brief Graph reader: BusLoad history in permille, 0 = oldest. */\nstatic uint16_t busLoadAt(void *, uint8_t index)\n{\n    return openknx.busLoad.historyAt(index);\n}\n\nvoid WidgetIPInterface::drawBus(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"KNX Bus\", PAGE_COUNT, PAGE_BUS);\n\n    TpUartDataLinkLayer *dll = knx.bau().getDataLinkLayer();\n    if (!dll)\n    {\n        Ui::rowAt(d, 28, \"No TP link\", nullptr);\n        return;\n    }\n    auto &st = dll->getTPUart().getStatistics();\n\n    // Compact units (OGM-Common Helper): raw counters reach 8-10 digits on a busy bus.\n    Ui::bigValue(d, 14, humanBytes(openknx.busLoad.currentBytesPerSec()).c_str(), \"/s\");\n\n    char b[24];\n    snprintf(b, sizeof(b), \"TX %s  RX %s\", humanCount(st.getTxFrames()).c_str(), humanCount(st.getRxFrames()).c_str());\n    Ui::rowAt(d, 32, b, nullptr);\n    snprintf(b, sizeof(b), \"RX %s  Rep %s\", humanBytes(st.getRxFrameBytes()).c_str(), humanCount(st.getRxRepetitions()).c_str());\n    Ui::rowAt(d, 40, b, nullptr);\n\n    // Last 60 s of line occupancy, fixed scale 0..100 %.\n    d.setCursor(0, 50);\n    d.print(\"%\");\n    Ui::graph(d, 8, 50, 119, 13, 2, openknx.busLoad.historyCount(), busLoadAt, nullptr);\n}", "cat-15": "// OFM-Network/src/OpenKNX/Network/Widgets/WidgetNetSpeed.cpp\n\n// Read the packet counters, turn the per-window delta into packets/s, push into the history ring.\nvoid WidgetNetSpeed::sample()\n{\n    const uint32_t now = millis();\n    if (now - _lastSample < SAMPLE_INTERVAL_MS) return;\n    const uint32_t dtMs = now - _lastSample;\n    _lastSample = now;\n\n    uint32_t rxCount = 0, txCount = 0;\n#ifdef OPENKNX_NET_HAVE_LAN_TRAFFIC\n    openknxLanTraffic(rxCount, txCount); // cumulative packet counters\n#endif\n\n    const bool haveBase = _haveBase;\n    if (haveBase && dtMs > 0)\n    {\n        _rxRate = (uint32_t)((uint64_t)(rxCount - _lastRxPackets) * 1000u / dtMs); // uint32 delta wraps safely\n        _txRate = (uint32_t)((uint64_t)(txCount - _lastTxPackets) * 1000u / dtMs);\n    }\n    _lastRxPackets = rxCount;\n    _lastTxPackets = txCount;\n    _haveBase = true;\n    if (!haveBase) return; // the first sample only takes the base, it pushes no bar\n\n    _rxHist[_histHead] = (uint16_t)(_rxRate > 0xFFFF ? 0xFFFF : _rxRate);\n    _txHist[_histHead] = (uint16_t)(_txRate > 0xFFFF ? 0xFFFF : _txRate);\n    _histHead = (_histHead + 1) % SPARK_LEN;\n    if (_histCount < SPARK_LEN) _histCount++;\n}\n\n// Mirror graph in [0,y,W,h]: centre baseline, TX bars up, RX bars down, shared scale, newest at the right.\nvoid WidgetNetSpeed::drawMirror(int16_t y, int16_t h, uint32_t scale)\n{\n    auto *g = _display->display;\n    const int16_t W = (int16_t)_display->GetDisplayWidth();\n    const int16_t mid = y + h / 2;\n    const int16_t half = h / 2 - 1;\n    if (scale == 0) scale = 1;\n\n    for (int16_t i = 0; i < W; i += 3) g->drawPixel(i, mid, WHITE); // faint baseline (dotted)\n\n    for (int16_t i = 0; i < W && i < SPARK_LEN; i++)\n    {\n        int idx = (_histHead - 1 - i + SPARK_LEN) % SPARK_LEN;\n        const int16_t x = W - 1 - i;\n        int16_t tb = (int16_t)((uint64_t)_txHist[idx] * half / scale);\n        int16_t rb = (int16_t)((uint64_t)_rxHist[idx] * half / scale);\n        if (tb > half) tb = half;\n        if (rb > half) rb = half;\n        if (tb > 0) g->drawFastVLine(x, mid - tb, tb, WHITE);\n        if (rb > 0) g->drawFastVLine(x, mid + 1, rb, WHITE);\n    }\n}\n\n// Text at (x + 1, 34) on a black field 2 px wider than the text (peak and span label of the mirror graph).\nvoid WidgetNetSpeed::drawLabel(int16_t x, const char *text)\n{\n    _display->display->fillRect(x, 33, (int16_t)strlen(text) * Ui::CharW + 2, 9, BLACK);\n    _display->display->setCursor(x + 1, 34);\n    _display->display->print(text);\n}\n\nvoid WidgetNetSpeed::draw()\n{\n    auto *g = _display->display;\n    Ui::begin(*g);\n    g->clearDisplay();\n    Ui::header(*g, \"LAN traffic\"); // fixed: the rotation keys on the widget name, not on this title\n\n#ifndef WIDGET_NETSPEED_HAVE_COUNTERS\n    // No packet counter in this build: \"n/a\" instead of a permanently-zero graph, logged once.\n    static bool warnedNoCounters = false;\n    if (!warnedNoCounters)\n    {\n        warnedNoCounters = true;\n        logInfoP(\"net-speed: this build has no packet counter\");\n    }\n    Ui::row(*g, 0, \"Speed\", \"n/a\", 6);\n    _display->displayBuff();\n    return;\n#endif\n\n    // shared scale = running max of either direction\n    uint32_t scale = 1;\n    for (uint8_t i = 0; i < _histCount; i++)\n    {\n        if (_rxHist[i] > scale) scale = _rxHist[i];\n        if (_txHist[i] > scale) scale = _txHist[i];\n    }\n\n    // two big values: TX (up) left up to the RX arrow, RX (down) right up to the edge\n    drawArrow(0, 15, true);\n    drawRate(7, 64, _txRate);\n    drawArrow(66, 15, false);\n    drawRate(73, (int16_t)_display->GetDisplayWidth(), _rxRate);\n\n    // mirror history, peak label left and time span right, both on a black field over the bars\n    drawMirror(32, 32, scale);\n    char pk[12], pu[8];\n    fmtParts(scale, pk, sizeof(pk), pu, sizeof(pu));\n    if (_histCount == 0) snprintf(pk, sizeof(pk), \"-\"); // no rate yet\n    drawLabel(0, pk);\n    drawLabel((int16_t)(_display->GetDisplayWidth() - (int16_t)strlen(SPAN_TEXT) * Ui::CharW - 2), SPAN_TEXT);\n\n    _display->displayBuff();\n}", "cat-16": "// OFM-Network/src/OpenKNX/Network/Widgets/WidgetWifi.cpp\n\nvoid drawWifiSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawBitmap(47, 3, kWifiArcs, 35, 21, WHITE);\n    d.fillCircle(64, 26, 2, WHITE);\n}\n\n/** @brief Client or offline card: word, badge and one detail line. */\nvoid drawCard(Adafruit_SSD1306 &d, const Info &info, uint8_t pages)\n{\n    const bool online = info.state == State::Client;\n    char b[24]; // the card shows 21 columns; printCentred cuts a longer text the same way\n    const char *detail = b;\n    if (online && info.rssi)\n        snprintf(b, sizeof(b), \"%s %d dBm\", info.ssid, (int)info.rssi);\n    else if (online)\n        detail = info.ssid; // no RSSI read yet\n    else if (info.ssid[0] && strlen(info.ssid) <= 12)\n        snprintf(b, sizeof(b), \"retrying %s\", info.ssid); // 21 columns\n    else if (info.ssid[0])\n        detail = info.ssid; // 13+ characters: the SSID alone, from 22 on cut to 18 + \"...\" by printCentred\n    else\n        detail = \"No credentials\"; // size 2 holds 10 characters: the word stays \"No WiFi\"\n    Ui::statusCard(d, drawWifiSymbol, online ? Ui::kBadgeOk : Ui::kBadgeError, online ? \"Online\" : \"No WiFi\", detail);\n    Ui::pageDots(d, pages, 0);\n}\n\nuint16_t rssiPermille(int16_t rssi)\n{\n    const int16_t v = (int16_t)((rssi - RssiFloor) * 1000 / RssiRange);\n    return v < 0 ? 0 : v > 1000 ? 1000 : (uint16_t)v;\n}\n\n/** @brief Graph reader over the module's RSSI history; 0 dBm (no connection) is a gap. */\nuint16_t rssiAt(void *, uint8_t index)\n{\n    const int8_t rssi = openknxNetwork.wifiRssiHistAt(index);\n    return rssi == 0 ? Ui::GraphGap : rssiPermille(rssi);\n}\n\n/** @brief Expert page: RSSI large, level bars, 10 min history with the -75 dBm limit. */\nvoid drawSignal(Adafruit_SSD1306 &d, const Info &info, uint8_t pages)\n{\n    Ui::header(d, \"WiFi\", pages, 1);\n    char b[6];\n    if (info.rssi)\n        snprintf(b, sizeof(b), \"%d\", (int)info.rssi);\n    else\n        snprintf(b, sizeof(b), \"-\");\n    Ui::bigValue(d, 14, b, \"dBm\");\n\n    const uint8_t level = info.rssi ? signalLevel(info.rssi) : 0;\n    for (uint8_t i = 0; i < 4; i++)\n    {\n        const int16_t x = 104 + i * 6, h = 3 + i * 3;\n        if (i < level)\n            d.fillRect(x, 28 - h, 4, h, WHITE);\n        else\n            d.drawFastHLine(x, 27, 4, WHITE);\n    }\n\n    const int16_t W = d.width();\n    for (int16_t y = GraphY; y < GraphY + GraphH; y += 3) d.drawPixel(0, y, WHITE); // grid\n    const int16_t limitY = (int16_t)(GraphY + GraphH - 1 - rssiPermille(RssiLimit) * (GraphH - 1) / 1000);\n    for (int16_t x = 0; x < W; x += 4) d.drawFastHLine(x, limitY, 2, WHITE); // limit, 2 on 2 off\n    Ui::graph(d, 0, GraphY, W - 1, GraphH, 2, openknxNetwork.wifiRssiHistCount(), rssiAt, nullptr);\n\n    // 60 samples of 10 s (WifiSetup.cpp WIFI_RSSI_SAMPLE_MS, Module.h WIFI_HIST_LEN)\n    d.fillRect(W - 38, GraphY - 1, 38, 9, BLACK);\n    d.setCursor(W - 37, GraphY);\n    d.print(\"10 min\");\n}\n\n/** @brief Expert page: network, level word, channel, security, address. */\nvoid drawDetails(Adafruit_SSD1306 &d, const Info &info, uint8_t pages)\n{\n    static const char *const levels[] = {\"-\", \"weak\", \"fair\", \"good\", \"very good\"};\n    Ui::header(d, openknxNetwork.localUsesStaticIp() ? \"WiFi FIX\" : \"WiFi DHCP\", pages, 2);\n    Ui::rowIcon(d, 0, Ui::kRowWifi, info.ssid);\n    Ui::rowIcon(d, 1, Ui::kRowInfo, \"Signal\", levels[info.rssi ? signalLevel(info.rssi) : 0]);\n    char b[16];\n    snprintf(b, sizeof(b), \"%u\", (unsigned)info.channel);\n    Ui::rowIcon(d, 2, Ui::kRowInfo, \"Channel\", b);\n    Ui::rowIcon(d, 3, Ui::kRowLock, \"Security\", securityText(info.security));\n    Ui::rowIcon(d, 4, Ui::kRowLan, \"IP\", localIp(b));\n}\n\n/** @brief Last page in client and offline state: host name, link and how long it has been up or down. */\nvoid drawNetwork(Adafruit_SSD1306 &d, uint8_t pages, uint8_t page)\n{\n    Ui::header(d, \"Network\", pages, page);\n    // No \"Host\" label: from 15 characters on it would be cut to a stub; the icon stands for it.\n    Ui::rowIcon(d, 0, Ui::kRowInfo, openknxNetwork.hostName());\n    const bool up = openknxNetwork.established();\n    Ui::rowIcon(d, 1, up ? Ui::kRowOk : Ui::kRowErr, \"Link\", up ? \"up\" : \"down\");\n    // Built on uptime() seconds, so it survives the millis() rollover; \"9999d 23:59:59\" leaves 4 label columns.\n    const uint32_t netUp = openknxNetwork.netUptimeSec();\n    const uint32_t netDown = openknxNetwork.netDowntimeSec();\n    if (netUp > 0)\n        Ui::rowIcon(d, 2, Ui::kRowClock, \"Up\", humanDuration(netUp).c_str());\n    else if (netDown > 0)\n        Ui::rowIcon(d, 2, Ui::kRowClock, \"Down\", humanDuration(netDown).c_str());\n    else\n        Ui::rowIcon(d, 2, Ui::kRowClock, \"Up\", \"-\");\n}\n\nvoid drawApSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawRoundRect(50, 14, 28, 12, 2, WHITE); // router box with two LEDs\n    d.fillRect(54, 18, 2, 2, WHITE);\n    d.fillRect(58, 18, 2, 2, WHITE);\n    d.drawFastVLine(70, 3, 11, WHITE); // antenna\n    d.drawBitmap(64, 0, kApArcs, 12, 4, WHITE);\n    d.fillCircle(70, 5, 1, WHITE);\n}\n\n/** @brief Own AP, page 1: card with the station count. */\nvoid drawOwnApCard(Adafruit_SSD1306 &d, const Info &info)\n{\n    char c[12];\n    Ui::statusCard(d, drawApSymbol, Ui::kBadgeOk, \"AP on\", clientsText(c, info.clients));\n    Ui::pageDots(d, 2, 0);\n}\n\n/** @brief Own AP, page 2: the AP's values. */\nvoid drawOwnAp(Adafruit_SSD1306 &d, const Info &info)\n{\n    Ui::header(d, \"WiFi AP\", 2, 1);\n    Ui::rowIcon(d, 0, Ui::kRowWifi, info.ssid);\n    Ui::rowIcon(d, 1, Ui::kRowLock, \"Security\", securityText(info.security));\n    char b[16];\n    snprintf(b, sizeof(b), \"%u\", (unsigned)info.channel);\n    Ui::rowIcon(d, 2, Ui::kRowInfo, \"Channel\", b);\n    Ui::rowIcon(d, 3, Ui::kRowLan, \"IP\", localIp(b));\n    snprintf(b, sizeof(b), \"%u\", (unsigned)info.clients);\n    Ui::rowIcon(d, 4, Ui::kRowInfo, \"Clients\", b);\n}", "cat-17": "// OFM-Network/src/OpenKNX/Network/Widgets/WidgetWifi.cpp\n\n/** @brief r * sin(deg) rounded to the nearest pixel, halves away from zero. */\nint16_t polar(int16_t r, uint16_t deg)\n{\n    const int32_t v = r * sinQ14(deg);\n    return (int16_t)(v >= 0 ? (v + 8192) >> 14 : -((-v + 8192) >> 14));\n}\n\n/**\n * @brief Countdown ring at (cx,cy): from 12 o'clock clockwise 2 px thick for the part left, dotted every 12 degrees\n * for the part gone. left <= span, both in the same unit.\n */\nvoid drawRing(Adafruit_SSD1306 &d, int16_t cx, int16_t cy, int16_t r, uint32_t left, uint32_t span)\n{\n    for (uint16_t a = 0; a < 360; a += 2)\n    {\n        const uint16_t c = (uint16_t)((a + 270) % 360); // y grows downwards: -r cos(a) = r sin(a + 270)\n        if ((uint64_t)a * span <= (uint64_t)360 * left)\n        {\n            d.drawPixel(cx + polar(r, a), cy + polar(r, c), WHITE);\n            d.drawPixel(cx + polar(r - 1, a), cy + polar(r - 1, c), WHITE);\n        }\n        else if (a % 12 == 0)\n            d.drawPixel(cx + polar(r, a), cy + polar(r, c), WHITE);\n    }\n}\n\n/**\n * @brief Setup AP, page 1: QR left, title, hint and station count in the right column.\n */\nvoid WidgetWifi::drawSetupQr(Adafruit_SSD1306 &d, const char *ssid, uint8_t clients)\n{\n    if (!buildQr(ssid))\n    {\n        Ui::header(d, \"WiFi Setup\", 2, 0);\n        Ui::printCentred(d, 24, \"Join WiFi\");\n        Ui::printCentred(d, 34, ssid);\n        return;\n    }\n\n    // QR as large as the height allows, left square: dark modules on a white field with a 3 px quiet zone\n    const int16_t H = d.height();\n    WidgetQRCode::drawQr(_display, _qr, 0, 0, H, H, 3, true);\n\n    constexpr int16_t X = 68; // right column, clear of the 64 px QR field\n    d.setCursor(X, 0);\n    d.print(\"WiFi\");\n    d.drawFastHLine(X - 2, Ui::HeaderLine, d.width() - (X - 2), WHITE);\n    Ui::pageDots(d, 2, 0);\n    d.setCursor(X, 14);\n    d.print(\"Scan to\");\n    d.setCursor(X, 23);\n    d.print(\"set up\");\n    // Remaining time only while the AP has a deadline; a connected station keeps the AP open.\n    uint32_t span = 0;\n    const uint32_t left = openknxNetwork.wifiApTimeLeftMs(&span);\n    if (clients == 0 && left > 0 && span >= left)\n    {\n        drawRing(d, 76, 46, 8, left, span);\n        char t[12]; // \"10:00\" at most; sized for any uint32_t\n        const uint32_t s = left / 1000;\n        snprintf(t, sizeof(t), \"%u:%02u\", (unsigned)(s / 60), (unsigned)(s % 60));\n        d.setCursor(88, 43);\n        d.print(t);\n    }\n    char c[12];\n    d.setCursor(X, 56);\n    d.print(clientsText(c, clients));\n}\n\n/** @brief Setup AP, page 2: where to open the setup page. */\nvoid drawSetupInfo(Adafruit_SSD1306 &d, const Info &info)\n{\n    Ui::header(d, \"WiFi Setup\", 2, 1);\n    Ui::printCentred(d, 14, info.ssid);\n    Ui::printCentred(d, 24, \"Open in browser\");\n    char ip[16], b[24];\n    snprintf(b, sizeof(b), \"%s/wifi\", localIp(ip));\n    Ui::printCentred(d, 34, b);\n    char c[12];\n    Ui::printCentred(d, 44, clientsText(c, info.clients));\n    Ui::printCentred(d, 54, \"open network\");\n}", "cat-18": "// OFM-Network/src/OpenKNX/Network/Widgets/WidgetNetInfo.cpp\n\n/** @brief Card symbol: RJ45 socket seen from the front (body, 8 contacts, latch slot) in x46..77 y3..24. */\nvoid drawJack(Adafruit_SSD1306 &d)\n{\n    d.drawRect(46, 3, 32, 17, WHITE);\n    d.drawFastHLine(56, 19, 12, BLACK); // opening of the latch slot\n    d.drawFastVLine(56, 19, 6, WHITE);\n    d.drawFastVLine(67, 19, 6, WHITE);\n    d.drawFastHLine(56, 24, 12, WHITE);\n    for (int16_t x = 51; x <= 72; x += 3)\n        d.drawFastVLine(x, 6, 5, WHITE);\n}\n\nvoid WidgetNetInfo::draw()\n{\n    Adafruit_SSD1306 &d = *_display->display;\n    Ui::begin(d);\n    d.clearDisplay();\n    // phyMode() is a stub, so established() (connected AND a non-zero IP) is the link indicator.\n    const bool up = openknxNetwork.established();\n#ifdef KNX_IP_WIFI\n    drawDetails(d, up);\n#else\n    if (_page == 0)\n        drawCard(d, up);\n    else\n        drawDetails(d, up);\n#endif\n    _display->displayBuff();\n}\n\n/** @brief Page 0: RJ45 socket, badge, \"Online\" with the address and how it was assigned, or the outage. */\nvoid WidgetNetInfo::drawCard(Adafruit_SSD1306 &d, bool up)\n{\n    char b[24];\n    if (up)\n    {\n        char ip[16];\n        formatIp(ip);\n        snprintf(b, sizeof(b), \"%s %s\", ip, method()); // 15 + 1 + 4 = 20 characters at most\n        Ui::statusCard(d, drawJack, Ui::kBadgeOk, \"Online\", b);\n    }\n    else\n        Ui::statusCard(d, drawJack, Ui::kBadgeError, \"No LAN\", \"Check cable\");\n    Ui::pageDots(d, 2, 0);\n}\n\n/** @brief Page 1: host name, IP, link and link age as icon rows; the assignment method sits in the title. */\nvoid WidgetNetInfo::drawDetails(Adafruit_SSD1306 &d, bool up)\n{\n    // A 15-character IP keeps its row because the method is in the title. Showing an IP while the\n    // link is down would only ever be a stale one.\n    const char *title = _name.c_str();\n    char b[24];\n    if (up)\n    {\n        snprintf(b, sizeof(b), \"%s %s\", title, method());\n        title = b;\n    }\n    Ui::header(d, title, PAGES, PAGES - 1);\n\n    // No \"Host\" label: from 15 characters on it would be cut to a stub; the icon stands for it.\n    Ui::rowIcon(d, 0, Ui::kRowInfo, openknxNetwork.hostName());\n\n    char ip[16];\n    if (up)\n        formatIp(ip);\n    else\n        snprintf(ip, sizeof(ip), \"-\"); // ASCII placeholder (SSD1306 CP437 has no em dash)\n#ifdef KNX_IP_WIFI\n    Ui::rowIcon(d, 1, Ui::kRowWifi, \"IP\", ip);\n#else\n    Ui::rowIcon(d, 1, Ui::kRowLan, \"IP\", ip);\n#endif\n    Ui::rowIcon(d, 2, up ? Ui::kRowOk : Ui::kRowErr, \"Link\", up ? \"up\" : \"down\");\n\n    // Age of the current link, or of the ongoing outage. Built on uptime() seconds, so it survives\n    // the 49.7-day millis() rollover. Short labels: \"9999d 23:59:59\" leaves 4 columns for the text.\n    const uint32_t netUp = openknxNetwork.netUptimeSec();\n    const uint32_t netDown = openknxNetwork.netDowntimeSec();\n    if (netUp > 0)\n        Ui::rowIcon(d, 3, Ui::kRowClock, \"Up\", humanDuration(netUp).c_str());\n    else if (netDown > 0)\n        Ui::rowIcon(d, 3, Ui::kRowClock, \"Down\", humanDuration(netDown).c_str());\n    else\n        Ui::rowIcon(d, 3, Ui::kRowClock, \"Up\", \"-\");\n}", "cat-19": "// OGM-Common/src/OpenKNX/Widgets/WidgetSysInfo.cpp\n\n/** @brief Card symbol: chip with four pins on each side, in x47..80 y0..27. */\nvoid drawChipSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawRoundRect(52, 4, 24, 20, 2, WHITE);\n    d.drawRect(58, 10, 12, 8, WHITE);\n    for (int16_t i = 0; i < 4; i++)\n    {\n        d.drawFastHLine(47, (int16_t)(7 + i * 4), 5, WHITE);\n        d.drawFastHLine(76, (int16_t)(7 + i * 4), 5, WHITE);\n    }\n    for (int16_t i = 0; i < 4; i++)\n    {\n        d.drawFastVLine((int16_t)(56 + i * 5), 0, 4, WHITE);\n        d.drawFastVLine((int16_t)(56 + i * 5), 24, 4, WHITE);\n    }\n}\n\n/** @brief Check mark and \"Running\"; warning and \"Restarted\" while the watchdog reset counter is not 0. */\nvoid WidgetSysInfo::drawCard(Adafruit_SSD1306 &d)\n{\n    char detail[24];\n    snprintf(detail, sizeof(detail), \"Up %s\", openknx.logger.buildUptime().c_str());\n    // Without the watchdog the counter sits in uninitialised RAM and is never written.\n#if defined(OPENKNX_WATCHDOG) && !defined(OPENKNX_DEBUGGER)\n    const bool restarted = openknx.watchdog.resets() > 0;\n#else\n    const bool restarted = false;\n#endif\n    Ui::statusCard(d, drawChipSymbol, restarted ? Ui::kBadgeWarn : Ui::kBadgeOk, restarted ? \"Restarted\" : \"Running\", detail);\n    Ui::pageDots(d, PAGE_COUNT, PAGE_CARD);\n}\n\nvoid WidgetSysInfo::drawDevice(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Device\", PAGE_COUNT, PAGE_DEVICE);\n    uint8_t r = rowWrap(d, 0, \"ID\", openknx.info.firmwareName().c_str(), 3);\n    Ui::row(d, r++, \"SN\", openknx.info.humanSerialNumber().c_str(), 3);\n    Ui::row(d, r, \"PA\", openknx.info.humanIndividualAddress().c_str(), 3);\n}\n\nvoid WidgetSysInfo::drawFirmware(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Firmware\", PAGE_COUNT, PAGE_FIRMWARE);\n    Ui::row(d, 0, \"Version\", openknx.info.humanFirmwareVersion().c_str(), 8);\n    Ui::row(d, 1, \"Number\", openknx.info.humanFirmwareNumber().c_str(), 8);\n    Ui::row(d, 2, \"KNX\", knxTypeLabel(MASK_VERSION).c_str(), 8);\n}\n\nvoid WidgetSysInfo::drawRuntime(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Runtime\", PAGE_COUNT, PAGE_RUNTIME);\n    char b[24];\n    snprintf(b, sizeof(b), \"%.1f KiB\", (float)freeMemory() / 1024.0f);\n    Ui::row(d, 0, \"Free\", b, 7);\n\n    // PSRAM only exists on ESP32 boards that have it: elsewhere the row is left out and Uptime moves up.\n    uint8_t r = 1;\n#if defined(ARDUINO_ARCH_ESP32) && defined(BOARD_HAS_PSRAM)\n    snprintf(b, sizeof(b), \"%.0f KiB\", (float)ESP.getFreePsram() / 1024.0f);\n    Ui::row(d, r++, \"PSRAM\", b, 7);\n#endif\n    Ui::row(d, r, \"Uptime\", openknx.logger.buildUptime().c_str(), 7);\n}\n\nvoid WidgetSysInfo::drawDiagnostics(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Diagnostics\", PAGE_COUNT, PAGE_DIAGNOSTICS);\n    char b[24];\n\n    // The low-water mark, not the current value: a leak shows there.\n    snprintf(b, sizeof(b), \"%.1f KiB\", (float)openknx.common.freeMemoryMin() / 1024.0f);\n    Ui::row(d, 0, \"Heap min\", b, 9);\n\n#ifdef OPENKNX_DUALCORE\n    snprintf(b, sizeof(b), \"%i/%i B\", openknx.common.freeStackMin(), openknx.common.freeStackMin1());\n#else\n    snprintf(b, sizeof(b), \"%i B\", openknx.common.freeStackMin());\n#endif\n    Ui::row(d, 1, \"Stack\", b, 9);\n\n    // Consecutive watchdog restarts and the reset period.\n    if (openknx.watchdog.active())\n        snprintf(b, sizeof(b), \"%u (%us)\", (unsigned)openknx.watchdog.resets(), (unsigned)openknx.watchdog.maxPeriod());\n    else\n        snprintf(b, sizeof(b), \"off\");\n    Ui::row(d, 2, \"Watchdog\", b, 9);\n\n#if defined(ARDUINO_ARCH_ESP32)\n    snprintf(b, sizeof(b), \"%s %u MHz\", ESP.getChipModel(), (unsigned)getCpuFrequencyMhz());\n#elif defined(ARDUINO_ARCH_RP2040)\n    snprintf(b, sizeof(b), \"RP %u MHz\", (unsigned)(F_CPU / 1000000UL));\n#else\n    snprintf(b, sizeof(b), \"-\");\n#endif\n    Ui::row(d, 3, \"Chip\", b, 9);\n}", "cat-20": "// OGM-Common/src/OpenKNX/Widgets/WidgetKnxBcu.cpp\n\n/** @brief Card symbol: three devices on a two-wire bus line in x40..79 y2..23, clear of six page dots from x80. */\nstatic void drawBusSymbol(Adafruit_SSD1306 &d)\n{\n    int8_t i = 0;\n    for (int16_t x = 42; x <= 68; x += 13, i++)\n    {\n        if (i == s_litDevice)\n            d.fillRoundRect(x, 2, 11, 9, 1, WHITE);\n        else\n            d.drawRoundRect(x, 2, 11, 9, 1, WHITE);\n        d.drawFastVLine((int16_t)(x + 5), 11, 6, WHITE);\n    }\n    d.fillRect(40, 17, 40, 2, WHITE);\n    d.fillRect(40, 22, 40, 2, WHITE);\n}\n\n/** @brief Page 0, shown by the rotation: bus state as a card, the load as detail. */\nvoid WidgetKnxBcu::drawCard(Adafruit_SSD1306 &d, TpUartDataLinkLayer *dll)\n{\n    const uint8_t *badge = Ui::kBadgeError;\n    const char *word = \"Bus lost\";\n    const char *detail = \"Check KNX line\";\n    char b[24];\n    if (!dll)\n    {\n        word = \"No bus\";\n        detail = \"No TP link\";\n    }\n    else\n    {\n        TPUart::DataLinkLayer &tp = dll->getTPUart();\n        switch (tp.getBcuState())\n        {\n            case TPUart::BCU_UNINITIALIZED:\n                if (uptime() < 30) // only the first 30 s after boot count as start-up (wrap-safe seconds)\n                {\n                    badge = Ui::kBadgeClock;\n                    word = \"Starting\";\n                    detail = \"TP starting\";\n                }\n                break;\n            case TPUart::BCU_BUSMONITOR:\n                badge = nullptr;\n                word = \"Busmon\";\n                detail = \"Monitor active\";\n                break;\n            case TPUart::BCU_CONNECTED:\n                if (tp.busOperational()) // bus power loss shows here before the BCU state follows\n                {\n                    snprintf(b, sizeof(b), \"Load %s/s\", humanBytes(_lastLoad).c_str());\n                    badge = Ui::kBadgeOk;\n                    word = \"Bus OK\";\n                    detail = b;\n                }\n                break;\n            default: break; // disconnected: \"Bus lost\"\n        }\n    }\n    // Traffic light: a new frame since the last card draw lights the next device, no traffic none.\n    const uint32_t frames = (uint32_t)(_txFrames + _rxFrames);\n    s_litDevice = -1;\n    if (dll && _cardShown && frames != _lastFrames)\n    {\n        _blink = (uint8_t)((_blink + 1) % 3);\n        s_litDevice = (int8_t)_blink;\n    }\n    _lastFrames = frames;\n    _cardShown = true;\n    Ui::statusCard(d, drawBusSymbol, badge, word, detail);\n    Ui::pageDots(d, PAGE_COUNT, PAGE_CARD);\n}\n\n// Frame 10 px high with the fill 2 px inside, peak-hold marker, full-scale number right of it.\nvoid WidgetKnxBcu::drawLoadBar(Adafruit_SSD1306 &d, int16_t y)\n{\n    constexpr int16_t barW = 92, inner = barW - 2 * Ui::BarPad;\n    const uint16_t scale = _loadScale ? _loadScale : 1;\n    const uint16_t load = _lastLoad > scale ? scale : _lastLoad;\n    Ui::bar(d, 0, y, barW, (uint16_t)((uint32_t)load * 1000 / scale));\n\n    // Peak marker inside the frame (peak >= load, so at or right of the fill edge); none while the peak is 0.\n    if (_loadPeak > 0)\n    {\n        const uint16_t pk = _loadPeak > scale ? scale : _loadPeak;\n        int16_t px = (int16_t)(Ui::BarPad + (uint32_t)inner * pk / scale);\n        if (px > Ui::BarPad + inner - 1) px = (int16_t)(Ui::BarPad + inner - 1);\n        d.drawFastVLine(px, (int16_t)(y + 1), Ui::BarH - 2, WHITE);\n    }\n\n    char sc[8]; // scale <= 65535\n    snprintf(sc, sizeof(sc), \"%u\", (unsigned)scale);\n    d.setCursor((int16_t)(barW + 4), (int16_t)(y + 1));\n    d.print(sc);\n}\n\n/** @brief Page 1: BCU state, frames, load, peak and the load bar. */\nvoid WidgetKnxBcu::drawTraffic(Adafruit_SSD1306 &d, TpUartDataLinkLayer *dll)\n{\n    Ui::header(d, _name.c_str(), PAGE_COUNT, PAGE_TRAFFIC);\n    char b[24];\n    Ui::row(d, 0, \"Status\", dll ? dll->getTPUart().getBcuStateInfo() : \"-\", 7);\n    if (dll)\n        snprintf(b, sizeof(b), \"%s/%s\", humanCount(_txFrames).c_str(), humanCount(_rxFrames).c_str());\n    else\n        snprintf(b, sizeof(b), \"-\");\n    Ui::row(d, 1, \"TX/RX\", b, 7);\n    snprintf(b, sizeof(b), \"%s/s\", humanBytes(_lastLoad).c_str());\n    Ui::row(d, 2, \"Load\", dll ? b : \"-\", 7);\n    snprintf(b, sizeof(b), \"%s/s\", humanBytes(_loadPeak).c_str());\n    Ui::row(d, 3, \"Peak\", dll ? b : \"-\", 7);\n    drawLoadBar(d, 54);\n}\n\n/** @brief Page 2: byte counters and overflows; error counters with a check at 0, a warning otherwise. */\nvoid WidgetKnxBcu::drawBytes(Adafruit_SSD1306 &d, TpUartDataLinkLayer *dll)\n{\n    Ui::header(d, \"Bytes\", PAGE_COUNT, PAGE_BYTES);\n    if (!dll)\n    {\n        static const char *const kLabels[] = {\"Discarded\", \"Received\", \"Await\", \"Repeated\", \"Overflow\"};\n        for (uint8_t i = 0; i < 5; i++) Ui::rowIcon(d, i, nullptr, kLabels[i], \"-\");\n        return;\n    }\n    auto &st = dll->getTPUart().getStatistics();\n    Ui::rowIcon(d, 0, rowState(_discardedBytes), \"Discarded\", humanBytes(_discardedBytes).c_str());\n    Ui::rowIcon(d, 1, Ui::kRowBus, \"Received\", humanBytes(_receivedBytes).c_str());\n    Ui::rowIcon(d, 2, Ui::kRowInfo, \"Await\", humanCount(dll->getTPUart().getReceiver().getAwaitBytes()).c_str());\n    Ui::rowIcon(d, 3, Ui::kRowInfo, \"Repeated\", humanCount(st.getRxRepetitions()).c_str());\n\n    // UART / search buffer / frame buffer / TX frame buffer: the short form keeps all four on one row.\n    const uint32_t uart = st.getRxUartOverflow(), search = st.getRxSearchBufferOverflow();\n    const uint32_t frame = st.getRxFrameBufferOverflow(), tx = st.getTxOverflowFrameBuffer();\n    char b[24];\n    snprintf(b, sizeof(b), \"%s/%s/%s/%s\", humanCountShort(uart).c_str(), humanCountShort(search).c_str(),\n             humanCountShort(frame).c_str(), humanCountShort(tx).c_str());\n    Ui::rowIcon(d, 4, rowState((uint64_t)uart + search + frame + tx), \"Overflow\", b);\n}\n\n/** @brief Page 3: BCU connection, baud rate, individual address. */\nvoid WidgetKnxBcu::drawStatus(Adafruit_SSD1306 &d, TpUartDataLinkLayer *dll)\n{\n    Ui::header(d, \"Status\", PAGE_COUNT, PAGE_STATUS);\n    char b[12];\n    if (dll && dll->getTPUart().getBaudrate() > 0)\n        snprintf(b, sizeof(b), \"%lu\", (unsigned long)dll->getTPUart().getBaudrate());\n    else\n        snprintf(b, sizeof(b), \"-\");\n    Ui::row(d, 0, \"Status\", dll ? dll->getTPUart().getBcuStateInfo() : \"-\", 8);\n    Ui::row(d, 1, \"Baud\", b, 8);\n    Ui::row(d, 2, \"Address\", openknx.info.humanIndividualAddress().c_str(), 8);\n}\n\n/** @brief Page 4: BCU resets, disconnects, CON rescues. */\nvoid WidgetKnxBcu::drawHealth(Adafruit_SSD1306 &d, TpUartDataLinkLayer *dll)\n{\n    Ui::header(d, \"Health\", PAGE_COUNT, PAGE_HEALTH);\n    static const char *const kLabels[] = {\"Resets\", \"Disconnects\", \"CON rescues\"};\n    uint32_t v[3] = {};\n    if (dll)\n    {\n        auto &st = dll->getTPUart().getStatistics();\n        v[0] = st.getBcuResets();\n        v[1] = st.getBcuDisconnects();\n        v[2] = st.getBcuConRescues();\n    }\n    for (uint8_t i = 0; i < 3; i++)\n        Ui::rowIcon(d, i, dll ? rowState(v[i]) : nullptr, kLabels[i], dll ? humanCount(v[i]).c_str() : \"-\");\n}\n\n/** @brief Page 5: error counters of the NCN chip. */\nvoid WidgetKnxBcu::drawNcn(Adafruit_SSD1306 &d, TpUartDataLinkLayer *dll)\n{\n    Ui::header(d, \"NCN errors\", PAGE_COUNT, PAGE_NCN);\n    static const char *const kLabels[] = {\"Slave coll.\", \"Recv errors\", \"Tx errors\", \"Proto errors\", \"Temp warnings\"};\n    uint32_t v[5] = {};\n    if (dll)\n    {\n        auto &st = dll->getTPUart().getStatistics();\n        v[0] = st.getBcuSlaveCollisions();\n        v[1] = st.getBcuReceiveErrors();\n        v[2] = st.getBcuTransmitErrors();\n        v[3] = st.getBcuProtocolErrors();\n        v[4] = st.getBcuTempWarnings();\n    }\n    for (uint8_t i = 0; i < 5; i++)\n        Ui::rowIcon(d, i, dll ? rowState(v[i]) : nullptr, kLabels[i], dll ? humanCount(v[i]).c_str() : \"-\");\n}", "cat-21": "// OAM-IP-Router/src/DisplayWidgets/WidgetIPRouter.cpp\n\n/** @brief Card symbol: IP and TP boxes with arrows both ways, in x44..83 y1..27. */\nstatic void drawIpTpSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawRoundRect(44, 3, 17, 22, 2, WHITE);\n    d.setCursor(47, 10);\n    d.print(\"IP\");\n    d.drawRoundRect(67, 3, 17, 22, 2, WHITE);\n    d.setCursor(70, 10);\n    d.print(\"TP\");\n    d.drawFastHLine(61, 9, 6, WHITE);\n    d.fillTriangle(66, 9, 64, 7, 64, 11, WHITE);\n    d.drawFastHLine(61, 17, 6, WHITE);\n    d.fillTriangle(61, 17, 63, 15, 63, 19, WHITE);\n}\n\nvoid WidgetIPRouter::drawCard(Adafruit_SSD1306 &d)\n{\n    const uint8_t *badge = Ui::kBadgeError;\n    const char *word = \"No bus\";\n    const char *detail = \"No TP link\";\n    char b[24];\n\n    TpUartDataLinkLayer *dll = KNX_TP_DLL; // the secondary link on the router BAU\n    if (!openknxNetwork.established())\n    {\n        word = \"No LAN\";\n        detail = \"Check cable\";\n    }\n    else if (dll)\n    {\n        switch (dll->getTPUart().getBcuState())\n        {\n            case TPUart::BCU_DISCONNECTED:\n                detail = \"Check KNX line\";\n                break;\n            case TPUart::BCU_UNINITIALIZED:\n                // Only the first 30 s after boot count as start-up; later an uninitialised BCU means no bus.\n                if (uptime() >= 30) // wrap-safe seconds since boot\n                {\n                    detail = \"Check KNX line\";\n                    break;\n                }\n                badge = Ui::kBadgeClock;\n                word = \"Starting\";\n                detail = \"TP starting\";\n                break;\n            default:\n            {\n                // Bus power loss: bus-powered chip after ~3 unanswered probes, external NCN via VBUS; BCU state lags.\n                if (!dll->getTPUart().busOperational())\n                {\n                    detail = \"Check KNX line\";\n                    break;\n                }\n                const std::string load = humanBytes(openknx.busLoad.currentBytesPerSec());\n#ifdef KNX_TUNNELING\n                IpTunnelServer &ts = knx.bau().getIpTunnelServer();\n                const uint8_t n = ts.tunnelCount();\n                const KnxIpTunnelConnection *t = n == 1 ? ts.tunnelAt(0) : nullptr;\n                if (t)\n                {\n                    // One client: who it is; the load only while both fit the line.\n                    char ip[16];\n                    formatIp(t->IpAddress, ip, sizeof(ip));\n                    if (snprintf(b, sizeof(b), \"%s  %s/s\", ip, load.c_str()) > 21)\n                        snprintf(b, sizeof(b), \"%s\", ip);\n                }\n                else\n                    snprintf(b, sizeof(b), \"%u %s  %s/s\", (unsigned)n, n == 1 ? \"tunnel\" : \"tunnels\", load.c_str());\n#else\n                snprintf(b, sizeof(b), \"%s/s\", load.c_str());\n#endif\n                // A router routes all the time; the tunnels are the detail, not the state.\n                badge = Ui::kBadgeOk;\n                word = \"Routing\";\n                detail = b;\n                break;\n            }\n        }\n    }\n\n    Ui::statusCard(d, drawIpTpSymbol, badge, word, detail);\n    Ui::pageDots(d, PAGE_COUNT, PAGE_CARD);\n}\n\nvoid WidgetIPRouter::drawIPInfo(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, _name.c_str(), PAGE_COUNT, PAGE_IP);\n\n    if (openknxNetwork.established())\n    {\n        char b[16]; // \"255.255.255.255\"\n        Ui::row(d, 0, \"IP\", formatAddr(openknxNetwork.localIP(), b, sizeof(b)));\n        Ui::row(d, 1, \"GW\", formatAddr(openknxNetwork.gatewayIP(), b, sizeof(b)));\n        Ui::row(d, 2, \"DNS\", formatAddr(openknxNetwork.nameServerIP(), b, sizeof(b)));\n    }\n    else\n    {\n        d.drawBitmap(d.width() / 2 - 4, 20, x_icon, 8, 8, WHITE);\n        Ui::printCentred(d, 34, \"Disconnected\");\n        Ui::printCentred(d, 44, \"Check LAN Cable\");\n    }\n}\n\n// Role from the own address, routing group, TTL, tunnel use.\nvoid WidgetIPRouter::drawCoupler(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Coupler\", PAGE_COUNT, PAGE_COUPLER);\n\n    char b[24];\n    const uint16_t pa = knx.individualAddress();\n    const unsigned area = pa >> 12, line = (pa >> 8) & 0x0F, dev = pa & 0xFF;\n    if (!knx.configured())\n        snprintf(b, sizeof(b), \"Not programmed\"); // the coupler default 15.15.0 would read as a line coupler\n    else if (dev != 0)\n        snprintf(b, sizeof(b), \"No coupler %u.%u.%u\", area, line, dev); // a device part: misconfigured\n    else if (line == 0)\n        snprintf(b, sizeof(b), \"Area coupler %u.0\", area);\n    else\n        snprintf(b, sizeof(b), \"Line coupler %u.%u\", area, line);\n    Ui::row(d, 0, b, nullptr);\n\n    const char *group = IPRouterModule::routingGroup();\n    Ui::row(d, 1, \"Group\", group[0] ? group : \"-\", 8);\n\n    const int ttl = IPRouterModule::routingTtl();\n    if (ttl < 0)\n        snprintf(b, sizeof(b), \"-\");\n    else\n        snprintf(b, sizeof(b), \"%d\", ttl);\n    Ui::row(d, 2, \"TTL\", b, 8);\n\n#ifdef KNX_TUNNELING\n    IpTunnelServer &ts = knx.bau().getIpTunnelServer();\n    snprintf(b, sizeof(b), \"%u / %u\", (unsigned)ts.tunnelCount(), (unsigned)ts.tunnelMax());\n    Ui::row(d, 3, \"Tunnels\", b, 8);\n#endif\n}\n\n// Telegrams per direction: routed, dropped by the filter table, not delivered on that side (tunnel losses included).\nvoid WidgetIPRouter::drawRouting(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, \"Routing\", PAGE_COUNT, PAGE_ROUTING);\n\n    KnxIpCounters &c = knx.bau().getCounters();\n    const uint32_t v[6] = {c.routedToKnx(), c.routedToIp(), c.filteredToKnx(), c.filteredToIp(), c.lostToKnx(), c.lostToIp()};\n    static const char *const label[3] = {\"Routed\", \"Filter\", \"Lost\"};\n    // Columns under \"IP>TP\" and \"TP>IP\": humanCount() of a 32-bit counter is at most 5 characters.\n    Ui::row(d, 0, nullptr, \"IP>TP  TP>IP\", 8);\n    char b[16];\n    for (uint8_t i = 0; i < 3; i++)\n    {\n        snprintf(b, sizeof(b), \"%5s  %5s\", humanCount(v[2 * i]).c_str(), humanCount(v[2 * i + 1]).c_str());\n        Ui::row(d, (uint8_t)(i + 1), label[i], b, 8);\n    }\n}", "cat-22": "// OFM-SDCard/src/Widgets/WidgetSDCard.cpp\n\n/** @brief Card symbol: SD card with a cut corner and four contacts, in x53..75 y1..27. */\nvoid drawSdSymbol(Adafruit_SSD1306 &d)\n{\n    d.drawFastHLine(53, 1, 17, WHITE);\n    d.drawLine(69, 1, 75, 7, WHITE);\n    d.drawFastVLine(75, 7, 21, WHITE);\n    d.drawFastHLine(53, 27, 23, WHITE);\n    d.drawFastVLine(53, 1, 27, WHITE);\n    for (int16_t x = 56; x <= 68; x += 4)\n        d.fillRect(x, 4, 2, 6, WHITE);\n}\n\nvoid WidgetSDCard::drawCard(Adafruit_SSD1306 &d, uint64_t freeBytes, uint64_t totalBytes)\n{\n    // formatSize() returns one static buffer: copy the first value before the second call.\n    char freeText[12], detail[24];\n    snprintf(freeText, sizeof(freeText), \"%s\", sdCardModule.formatSize(freeBytes));\n    snprintf(detail, sizeof(detail), \"free of %s\", sdCardModule.formatSize(totalBytes));\n    Ui::statusCard(d, drawSdSymbol, nullptr, freeText, detail);\n    Ui::pageDots(d, _pages, 0);\n}\n\nvoid WidgetSDCard::drawDetails(Adafruit_SSD1306 &d, uint64_t usedBytes, uint64_t totalBytes)\n{\n    Ui::header(d, _name.c_str(), _pages, 1);\n    Ui::row(d, 0, \"Type\", sdCardModule.getCardType(true).c_str(), kLabelCols);\n    Ui::row(d, 1, \"Maker\", sdCardModule.getCardInfo().manufacturer.c_str(), kLabelCols);\n    Ui::row(d, 2, \"Total\", sdCardModule.formatSize(totalBytes), kLabelCols);\n    Ui::row(d, 3, \"Used\", sdCardModule.formatSize(usedBytes), kLabelCols);\n\n    // Used share as a bar with the percent after it, both on the last row.\n    const uint64_t permille = usedBytes * 1000 / totalBytes;\n    char pct[8];\n    snprintf(pct, sizeof(pct), \"%u%%\", (unsigned)(usedBytes * 100 / totalBytes));\n    const int16_t pctX = (int16_t)(d.width() - Ui::ValueEnd - (int16_t)strlen(pct) * Ui::CharW);\n    Ui::bar(d, 0, Ui::Row0 + 4 * Ui::Pitch, (int16_t)(d.width() - Ui::ValueEnd - kPctW - 4), (uint16_t)(permille > 1000 ? 1000 : permille));\n    d.setCursor(pctX, Ui::Row0 + 4 * Ui::Pitch);\n    d.print(pct);\n}\n\nvoid WidgetSDCard::drawFormat(Adafruit_SSD1306 &d)\n{\n    Ui::header(d, _name.c_str());\n    // Fine percent (0.01 % resolution) so the number visibly moves even on a huge card.\n    const uint16_t pm = sdCardModule.formatPermyriad(); // 0..10000 = 0.00..100.00 %\n    char b[12];\n    snprintf(b, sizeof(b), \"%u.%02u%%\", (unsigned)(pm / 100), (unsigned)(pm % 100));\n    Ui::printCentred(d, 14, b, 2);\n    Ui::bar(d, 0, 32, d.width(), (uint16_t)(pm / 10));\n    Ui::printCentred(d, 44, \"Formatting\");\n    Ui::printCentred(d, 54, sdCardModule.formatOpName());\n}\n\nvoid WidgetSDCard::drawState(Adafruit_SSD1306 &d, const char *const *lines, uint8_t count)\n{\n    drawSdSymbol(d);\n    for (uint8_t i = 0; i < count; i++)\n        Ui::printCentred(d, (int16_t)(34 + i * Ui::Pitch), lines[i]);\n}", "cat-23": "// OFM-SDCard/src/Widgets/WidgetFileBrowser.cpp\n\nvoid WidgetFileBrowser::drawScrollbar(Adafruit_SSD1306 &d, size_t first, size_t count)\n{\n    // Dots at x127 every second row y12..60, thumb x126..127 placed by the first visible row.\n    const int16_t track = (int16_t)(VISIBLE_ROWS * Ui::Pitch);\n    for (int16_t py = LIST_TOP; py < LIST_TOP + track; py += 2)\n        d.drawPixel(127, py, WHITE);\n    int16_t thumb = (int16_t)(track * (int32_t)VISIBLE_ROWS / (int32_t)count);\n    if (thumb < 4)\n        thumb = 4;\n    const int16_t ty = (int16_t)(LIST_TOP + (int32_t)(track - thumb) * (int32_t)first / (int32_t)(count - VISIBLE_ROWS));\n    d.fillRect(126, ty, 2, thumb, WHITE);\n}\n\nvoid WidgetFileBrowser::drawBrowser()\n{\n    if (!_display)\n        return;\n\n    const std::string path = currentPath();\n    const bool hasUp = !_atRootPath(path); // \"..\" up-entry shown in every non-root directory\n\n    // Total navigable rows = optional up-entry + cached entries (mock fEntries()).\n    const size_t upCount = hasUp ? 1 : 0;\n    const size_t total = upCount + _entries.size();\n\n    // Clamp the selection to the rows (reload() does the same) and refresh the scroll window.\n    if (total == 0)\n        _selectedIndex = 0;\n    else if (_selectedIndex >= total)\n        _selectedIndex = total - 1;\n    _updateWindow();\n    // A listing that shrank after a delete keeps the window full; the selection stays inside it.\n    if (total <= VISIBLE_ROWS)\n        _windowStart = 0;\n    else if (_windowStart > total - VISIBLE_ROWS)\n        _windowStart = total - VISIBLE_ROWS;\n\n    Adafruit_SSD1306 &d = *_display->display;\n    Ui::begin(d);\n    d.clearDisplay();\n\n    // Header: \"SD:<path>\" left (cut with \"...\"), \"(sel+1)/total\" right, dotted line.\n    char title[24];\n    snprintf(title, sizeof(title), \"SD:%s\", path.c_str());\n    Ui::headerPos(d, title, (uint16_t)(total == 0 ? 0 : _selectedIndex + 1), (uint16_t)total);\n\n    // Empty directory (no entries and no up-entry -> only possible at an empty root).\n    if (total == 0)\n    {\n        d.setCursor(TEXT_X, LIST_TOP + 1);\n        d.print(\"(empty)\");\n        _display->displayBuff();\n        return;\n    }\n\n    // Rows: inverse selection up to x123 and value cells ending at x123 when the scrollbar is drawn, else x127 / x125.\n    const bool scrollbar = total > VISIBLE_ROWS;\n    const int16_t rowW = scrollbar ? SCROLL_X : d.width();\n    const int16_t valueEnd = scrollbar ? SCROLL_X : (int16_t)(d.width() - Ui::ValueEnd);\n    const size_t windowEnd = std::min(total, _windowStart + VISIBLE_ROWS);\n    int16_t y = LIST_TOP;\n    for (size_t i = _windowStart; i < windowEnd; i++, y += Ui::Pitch)\n    {\n        const bool selected = (i == _selectedIndex);\n\n        // Label + right-aligned value; formatSize() is printed before any further call reuses its buffer.\n        const char *name = \"..\";    // Up-entry\n        const char *value = nullptr;\n        bool dir = false;\n        if (!(hasUp && i == 0))\n        {\n            const SdDirEntry &e = _entries[i - upCount];\n            name = e.name.c_str();\n            dir = e.isDir;\n            value = dir ? \"DIR\" : sdCardModule.formatSize(e.size);\n        }\n\n        if (selected)\n            d.fillRect(0, y, rowW, Ui::Pitch, WHITE);\n        d.setTextColor(selected ? BLACK : WHITE);\n\n        int16_t labelEnd = valueEnd; // the label ends 2 px before the value, else before valueEnd\n        if (value)\n        {\n            int16_t vx = (int16_t)(valueEnd - (int16_t)strlen(value) * Ui::CharW);\n            if (vx < 0)\n                vx = 0;\n            d.setCursor(vx, (int16_t)(y + 1));\n            d.print(value);\n            labelEnd = (int16_t)(vx - 2);\n        }\n        printName(d, (int16_t)(y + 1), name, dir, (int16_t)((labelEnd - TEXT_X) / Ui::CharW));\n    }\n\n    if (scrollbar)\n        drawScrollbar(d, _windowStart, total);\n    d.setTextColor(WHITE);\n    _display->displayBuff();\n}", "cat-24": "// OFM-Notify/src/Widgets/WidgetNotify.cpp\n\nvoid WidgetNotify::draw()\n{\n    State s;\n    openknxNotifyModule.displayState(s);\n#ifdef NFY_DISPLAY_FULL\n    // the fault page exists only while an account is failing; a page that went away falls back to the first\n    _pages = !openknxNotifyModule.displayPages() ? 1 : s.failed ? 3 : 2;\n    if (_page >= _pages)\n        _page = 0;\n#endif\n\n    Adafruit_SSD1306 *d = _display->display;\n    Ui::begin(*d);\n    d->clearDisplay();\n#ifdef NFY_DISPLAY_FULL\n    if (_page == 1)\n        drawAccounts();\n    else if (_page == 2)\n        drawFault(s);\n    else\n#endif\n        drawMain(s);\n    _display->displayBuff();\n}\n\nvoid WidgetNotify::drawMain(const State &s)\n{\n    // index: State::Mode\n    static const char *const kWord[] = {\"Ready\", \"Sending\", \"Muted\", \"Locked\", \"Waiting\", \"Waiting\", \"Error\"};\n    static const uint8_t *const kBadge[] = {Ui::kBadgeOk, nullptr, nullptr, Ui::kBadgeLock, Ui::kBadgeClock, Ui::kBadgeClock, Ui::kBadgeError};\n\n    Adafruit_SSD1306 *d = _display->display;\n    const int16_t ex = (int16_t)_display->GetDisplayWidth() / 2 - 20; // envelope 40 x 27\n    d->drawRect(ex, 1, 40, 27, WHITE);\n    d->drawLine(ex, 1, ex + 20, 16, WHITE);\n    d->drawLine(ex + 39, 1, ex + 20, 16, WHITE);\n#ifdef NFY_DISPLAY_FULL\n    Ui::pageDots(*d, _pages, _page);\n#endif\n\n    char buf[kCols + 1] = \"\";\n    const char *sub = buf;\n    switch (s.mode)\n    {\n        case State::Sending:\n            d->drawFastHLine(ex - 14, 6, 8, WHITE);\n            d->drawFastHLine(ex - 18, 13, 12, WHITE);\n            d->drawFastHLine(ex - 12, 20, 6, WHITE);\n            // fall through\n        case State::Locked:\n            if (s.queued)\n                snprintf(buf, sizeof buf, \"%u queued\", s.queued);\n            break;\n        case State::Muted:\n            for (int16_t o = -2; o <= 2; o++)\n                if (o)\n                    d->drawLine(ex - 4, 1 + o, ex + 44, 29 + o, BLACK);\n            d->drawLine(ex - 4, 1, ex + 44, 29, WHITE);\n            duration(buf, sizeof buf, s.muteLeftS, \"left\");\n            break;\n        case State::NoClock:\n            sub = \"no clock\";\n            break;\n        case State::NoNet:\n            sub = \"no network\";\n            break;\n        case State::Failed:\n        {\n            NotifyModule::DisplayAccount acc;\n            if (openknxNotifyModule.displayAccount(s.firstFailed, acc))\n            {\n                accountLabel(buf, kCols - 4, s.firstFailed, acc); // room for \" +99\"\n                if (s.failed > 1)\n                    snprintf(buf + strlen(buf), 5, \" +%u\", s.failed - 1);\n            }\n            break;\n        }\n        default:\n            if (s.lastAgeS == State::kNever)\n                sub = \"none yet\";\n            else if (s.lastAgeS == State::kNoTime)\n                sub = \"sent\";\n            else\n                duration(buf, sizeof buf, s.lastAgeS, \"ago\");\n            break;\n    }\n    if (kBadge[s.mode])\n    {\n        d->fillCircle(ex + 39, 24, 10, BLACK); // keeps the badge off the envelope\n        Ui::badge(*d, ex + 39, 24, kBadge[s.mode]);\n    }\n    Ui::printCentred(*d, 33, kWord[s.mode], 2);\n    Ui::printCentred(*d, 54, sub, 1);\n}\n\nvoid WidgetNotify::drawAccounts()\n{\n    Adafruit_SSD1306 *d = _display->display;\n    Ui::header(*d, \"Accounts\", _pages, _page);\n\n    NotifyModule::DisplayAccount acc;\n    uint8_t total = 0;\n    for (uint8_t a = 1; a <= NotifyModule::displayAccountCount(); a++)\n        total += openknxNotifyModule.displayAccount(a, acc);\n    if (!total)\n        return;\n    // more accounts than rows: a window that moves on every 3 s, so each one is reachable\n    const uint8_t win = (uint8_t)((millis() / 3000) % ((total + kRows - 1) / kRows));\n    uint8_t shown = 0;\n    for (uint8_t a = 1; a <= NotifyModule::displayAccountCount(); a++)\n    {\n        if (!openknxNotifyModule.displayAccount(a, acc))\n            continue;\n        const uint8_t i = shown++;\n        if (i / kRows != win)\n            continue;\n        const int16_t y = kRowY + (i % kRows) * kRowPitch;\n        char label[kCols + 1];\n        accountLabel(label, kCols - 2, a, acc);\n        d->drawBitmap(0, y - 1, acc.state == AccResult::Failed ? Ui::kRowErr : acc.state == AccResult::None ? kRowNone : Ui::kRowOk, 9, 9, WHITE);\n        d->setCursor(12, y);\n        d->print(label);\n    }\n}\n\nvoid WidgetNotify::drawFault(const State &s)\n{\n    Adafruit_SSD1306 *d = _display->display;\n    Ui::header(*d, \"Error\", _pages, _page);\n\n    NotifyModule::DisplayAccount acc;\n    if (!openknxNotifyModule.displayAccount(s.firstFailed, acc))\n        return;\n    Ui::badge(*d, 9, 23, Ui::kBadgeError);\n\n    char line[kCols + 1];\n    accountLabel(line, kCols - 4, s.firstFailed, acc);\n    d->setCursor(24, 14);\n    d->print(line);\n    if (acc.at && s.clock >= acc.at)\n    {\n        duration(line, sizeof line, s.clock - acc.at, \"ago\");\n        d->setCursor(24, 24);\n        d->print(line);\n    }\n\n    // only a fixed reason text and the code: the answer of a server stays off the display\n    int16_t y = 40;\n    const char *why = whyText(acc.why);\n    if (*why)\n    {\n        d->setCursor(0, y);\n        d->print(why);\n        y = 50;\n    }\n    if (acc.code)\n    {\n        snprintf(line, sizeof line, \"Code %u\", acc.code);\n        d->setCursor(0, y);\n        d->print(line);\n    }\n}"};
