class G{
  constructor(w=W,h=H){this.w=w;this.h=h;this.b=new Uint8Array(w*h);this.cx=0;this.cy=0;this.sz=1;this.fg=1;this.bg=1;this.wrap=true}
  clear(){this.b.fill(0)}
  px(x,y,c){x=Math.trunc(x);y=Math.trunc(y);if(x<0||y<0||x>=this.w||y>=this.h)return;const i=y*this.w+x;if(c===2)this.b[i]^=1;else this.b[i]=c?1:0}
  hl(x,y,w,c){for(let i=0;i<w;i++)this.px(x+i,y,c)}
  vl(x,y,h,c){for(let i=0;i<h;i++)this.px(x,y+i,c)}
  fr(x,y,w,h,c){for(let i=0;i<w;i++)this.vl(x+i,y,h,c)}
  rc(x,y,w,h,c){this.hl(x,y,w,c);this.hl(x,y+h-1,w,c);this.vl(x,y,h,c);this.vl(x+w-1,y,h,c)}
  ln(x0,y0,x1,y1,c){
    if(x0===x1){if(y0>y1)[y0,y1]=[y1,y0];this.vl(x0,y0,y1-y0+1,c);return}
    if(y0===y1){if(x0>x1)[x0,x1]=[x1,x0];this.hl(x0,y0,x1-x0+1,c);return}
    const st=Math.abs(y1-y0)>Math.abs(x1-x0);if(st){[x0,y0]=[y0,x0];[x1,y1]=[y1,x1]}
    if(x0>x1){[x0,x1]=[x1,x0];[y0,y1]=[y1,y0]}
    const dx=x1-x0,dy=Math.abs(y1-y0),ys=y0<y1?1:-1;let err=Math.trunc(dx/2);
    for(;x0<=x1;x0++){st?this.px(y0,x0,c):this.px(x0,y0,c);err-=dy;if(err<0){y0+=ys;err+=dx}}
  }
  ci(x0,y0,r,c){let f=1-r,dx=1,dy=-2*r,x=0,y=r;this.px(x0,y0+r,c);this.px(x0,y0-r,c);this.px(x0+r,y0,c);this.px(x0-r,y0,c);
    while(x<y){if(f>=0){y--;dy+=2;f+=dy}x++;dx+=2;f+=dx;
      this.px(x0+x,y0+y,c);this.px(x0-x,y0+y,c);this.px(x0+x,y0-y,c);this.px(x0-x,y0-y,c);
      this.px(x0+y,y0+x,c);this.px(x0-y,y0+x,c);this.px(x0+y,y0-x,c);this.px(x0-y,y0-x,c)}}
  cih(x0,y0,r,cn,c){let f=1-r,dx=1,dy=-2*r,x=0,y=r;while(x<y){if(f>=0){y--;dy+=2;f+=dy}x++;dx+=2;f+=dx;
    if(cn&4){this.px(x0+x,y0+y,c);this.px(x0+y,y0+x,c)}if(cn&2){this.px(x0+x,y0-y,c);this.px(x0+y,y0-x,c)}
    if(cn&8){this.px(x0-y,y0+x,c);this.px(x0-x,y0+y,c)}if(cn&1){this.px(x0-y,y0-x,c);this.px(x0-x,y0-y,c)}}}
  fch(x0,y0,r,cn,d,c){let f=1-r,dx=1,dy=-2*r,x=0,y=r,px=x,py=y;d++;
    while(x<y){if(f>=0){y--;dy+=2;f+=dy}x++;dx+=2;f+=dx;
      if(x<y+1){if(cn&1)this.vl(x0+x,y0-y,2*y+d,c);if(cn&2)this.vl(x0-x,y0-y,2*y+d,c)}
      if(y!==py){if(cn&1)this.vl(x0+py,y0-px,2*px+d,c);if(cn&2)this.vl(x0-py,y0-px,2*px+d,c);py=y}px=x}}
  fci(x0,y0,r,c){this.vl(x0,y0-r,2*r+1,c);this.fch(x0,y0,r,3,0,c)}
  rr(x,y,w,h,r,c){const m=Math.trunc((w<h?w:h)/2);if(r>m)r=m;this.hl(x+r,y,w-2*r,c);this.hl(x+r,y+h-1,w-2*r,c);this.vl(x,y+r,h-2*r,c);this.vl(x+w-1,y+r,h-2*r,c);
    this.cih(x+r,y+r,r,1,c);this.cih(x+w-r-1,y+r,r,2,c);this.cih(x+w-r-1,y+h-r-1,r,4,c);this.cih(x+r,y+h-r-1,r,8,c)}
  frr(x,y,w,h,r,c){const m=Math.trunc((w<h?w:h)/2);if(r>m)r=m;this.fr(x+r,y,w-2*r,h,c);this.fch(x+w-r-1,y+r,r,1,h-2*r-1,c);this.fch(x+r,y+r,r,2,h-2*r-1,c)}
  ft(x0,y0,x1,y1,x2,y2,c){
    if(y0>y1){[y0,y1]=[y1,y0];[x0,x1]=[x1,x0]}if(y1>y2){[y2,y1]=[y1,y2];[x2,x1]=[x1,x2]}if(y0>y1){[y0,y1]=[y1,y0];[x0,x1]=[x1,x0]}
    if(y0===y2){let a=x0,b=x0;if(x1<a)a=x1;else if(x1>b)b=x1;if(x2<a)a=x2;else if(x2>b)b=x2;this.hl(a,y0,b-a+1,c);return}
    const dx01=x1-x0,dy01=y1-y0,dx02=x2-x0,dy02=y2-y0,dx12=x2-x1,dy12=y2-y1;let sa=0,sb=0,y;const last=(y1===y2)?y1:y1-1;
    for(y=y0;y<=last;y++){let a=x0+Math.trunc(sa/dy01),b=x0+Math.trunc(sb/dy02);sa+=dx01;sb+=dx02;if(a>b)[a,b]=[b,a];this.hl(a,y,b-a+1,c)}
    sa=dx12*(y-y1);sb=dx02*(y-y0);
    for(;y<=y2;y++){let a=x1+Math.trunc(sa/dy12),b=x0+Math.trunc(sb/dy02);sa+=dx12;sb+=dx02;if(a>b)[a,b]=[b,a];this.hl(a,y,b-a+1,c)}}
  bm(x,y,d,w,h,c){const bw=(w+7)>>3;let b=0;for(let j=0;j<h;j++)for(let i=0;i<w;i++){if(i&7)b=(b<<1)&255;else b=d[j*bw+(i>>3)];if(b&0x80)this.px(x+i,y+j,c)}}
  ch(x,y,c,f,bg,s){if(c>=176)c++;for(let i=0;i<5;i++){let l=FONT[c*5+i];for(let j=0;j<8;j++,l>>=1){
      if(l&1){s===1?this.px(x+i,y+j,f):this.fr(x+i*s,y+j*s,s,s,f)}else if(bg!==f){s===1?this.px(x+i,y+j,bg):this.fr(x+i*s,y+j*s,s,s,bg)}}}
    if(bg!==f){s===1?this.vl(x+5,y,8,bg):this.fr(x+5*s,y,s,8*s,bg)}}
  pr(str){for(const k of str){const c=k.charCodeAt(0)&255;if(c===10){this.cx=0;this.cy+=8*this.sz;continue}if(c===13)continue;
      if(this.wrap&&this.cx+6*this.sz>this.w){this.cx=0;this.cy+=8*this.sz}this.ch(this.cx,this.cy,c,this.fg,this.bg,this.sz);this.cx+=6*this.sz}}
  t(x,y,s,sz=1,f=1,b){this.sz=sz;this.fg=f;this.bg=(b===undefined)?f:b;this.cx=x;this.cy=y;this.pr(s)}
}

/* ---------- formatters ported from OGM-Common Helper.cpp ---------- */
const tr=Math.trunc;
function humanCount(v){if(v<1e4)return ''+v;if(v<1e5)return tr(v/1e3)+'.'+tr(v%1e3/100)+'k';if(v<1e6)return tr(v/1e3)+'k';
  if(v<1e7)return tr(v/1e6)+'.'+String(tr(v%1e6/1e4)).padStart(2,'0')+'M';if(v<1e8)return tr(v/1e6)+'.'+tr(v%1e6/1e5)+'M';if(v<1e9)return tr(v/1e6)+'M';
  if(v<1e10)return tr(v/1e9)+'.'+String(tr(v%1e9/1e7)).padStart(2,'0')+'G';return tr(v/1e9)+'G'}
function humanCountShort(v){if(v<1e3)return ''+v;if(v<1e6)return tr(v/1e3)+'k';if(v<1e9)return tr(v/1e6)+'M';return tr(v/1e9)+'G'}
function humanBytes(v){if(v<1e4)return v+' B';if(v<1e5)return tr(v/1e3)+'.'+tr(v%1e3/100)+' kB';if(v<1e6)return tr(v/1e3)+' kB';
  if(v<1e7)return tr(v/1e6)+'.'+String(tr(v%1e6/1e4)).padStart(2,'0')+' MB';if(v<1e8)return tr(v/1e6)+'.'+tr(v%1e6/1e5)+' MB';if(v<1e9)return tr(v/1e6)+' MB';
  if(v<1e10)return tr(v/1e9)+'.'+String(tr(v%1e9/1e7)).padStart(2,'0')+' GB';return tr(v/1e9)+' GB'}
function duration(s,suffix){const min=tr(s/60)+(s%60!==0?1:0);const u=min<120?0:min<48*60?1:2;const dv=[1,60,1440][u];return tr((min+dv-1)/dv)+' '+['min','h','d'][u]+' '+suffix}
function humanDuration(s){const d=tr(s/86400),h=tr(s%86400/3600),m=tr(s%3600/60),x=s%60;const p=n=>String(n).padStart(2,'0');return d+'d '+p(h)+':'+p(m)+':'+p(x)}

/* ---------- sample data ---------- */
function rnd(i,seed){const x=Math.sin(i*12.9898+seed*78.233)*43758.5453;return x-Math.floor(x)}
function series(len,t,seed,base,amp,burst){const out=[];const now=Math.floor(t);for(let i=0;i<len;i++){const k=now-len+1+i;let v=base+amp*(0.5+0.5*Math.sin(k/7+seed))*rnd(k,seed);if(burst&&rnd(k,seed+9)>0.93)v+=burst*rnd(k,seed+3);out.push(Math.max(0,Math.round(v)))}return out}
const UPT=3*86400+4*3600+12*60+9;

/* ---------- shared pieces (ported) ---------- */
function dots(g,n,p){const s=W-12-n*6;for(let i=0;i<n;i++){const x=s+i*6+2;i===p?g.fci(x,4,2,1):g.ci(x,4,1,1)}}
function hdr(g,title,n,p){g.t(0,0,title);if(n>1)dots(g,n,p);g.ln(0,10,W,10,1)}
function mgr(g,mode){if(!mode)return;const bx=W-12,bm=mode==='bm';g.fr(bx,0,12,9,bm?1:0);
  if(bm)g.t(bx+1,1,'BM',1,0);else if(mode==='pause'){g.fr(bx+2,1,2,7,1);g.fr(bx+6,1,2,7,1)}else{for(let c=0;c<4;c++)g.vl(bx+3+c,1+c,7-2*c,1)}}
function centered(g,y,s,sz=1){g.t(tr((W-s.length*6*sz+sz)/2),y,s,sz)}
function ctext(g,y,s,sz=1,f=1,b){g.t(tr((W-s.length*6*sz+sz)/2),y,s,sz,f,b)} /* same centring as Notify and Ui::printCentred */
