/* string art -> bitmap bytes (MSB first, like drawBitmap) */
function art(rows,w){const h=rows.length,bw=(w+7)>>3,d=new Uint8Array(bw*h);rows.forEach((r,j)=>{for(let i=0;i<w;i++)if(r[i]==='#')d[j*bw+(i>>3)]|=0x80>>(i&7)});return d}

