def('ipif-overview',g=>{hdr(g,'Overview',5,0);g.t(0,14,'DHCP10.0.0.39');g.t(0,24,'GW  10.0.0.1');g.t(0,34,'DNS 10.0.0.1');g.t(0,44,'PA  1.1.250');mgr(g,'play')});
def('ipif-tunnels',g=>{hdr(g,'Tunnels',5,1);const cnt=3,mx=16;g.t(0,14,`Active  ${cnt} / ${mx}`);const p=tr(W/mx);
  for(let i=0;i<mx;i++){const x=i*p;i<cnt?g.fr(x,22,p-1,6,1):g.hl(x,27,p-1,1)}
  [['10.0.0.21','1.1.251'],['10.0.0.57','1.1.252'],['10.0.0.104','1.1.253']].forEach((l,i)=>g.t(0,32+8*i,l[0].padEnd(13)+l[1]));mgr(g,'play')});
def('ipif-bus',(g,t)=>{hdr(g,'KNX Bus',5,2);const sp=series(100,t,1,180,520,900);const cur=sp[99];
  g.t(0,14,`Load ${humanBytes(cur)}/s`);g.t(0,24,`TX ${humanCount(48211+tr(t)*3)}  RX ${humanCount(1203877+tr(t)*41)}`);g.t(0,34,`RX ${humanBytes(28417330+tr(t)*400)}  Rep ${humanCount(312)}`);
  const gx=2,gy=44,gh=18,base=gy+gh;let mx=1;sp.forEach(v=>{if(v>mx)mx=v});sp.forEach((v,i)=>{const h=tr(v*gh/mx);g.ln(gx+i,base-h,gx+i,base,1)});g.ln(gx,base+1,gx+100,base+1,1);mgr(g,'play')},true);
def('ipif-health',g=>{hdr(g,'Health',5,3);g.t(0,14,`Resets ${humanCountShort(0)} Disc ${humanCountShort(0)}`);g.t(0,24,`ConRescue ${humanCountShort(2)}`);
  g.t(0,34,`SC${humanCountShort(0)} RE${humanCountShort(1)} TE${humanCountShort(0)}`);g.t(0,44,`PE${humanCountShort(0)} TempWarn ${humanCount(0)}`);g.t(0,54,'State Connected');mgr(g,'play')});
def('ipif-status',g=>{hdr(g,'Status',5,4);g.t(0,14,'Link UP');g.t(0,24,'Bus  Connected');g.t(0,34,'IP   10.0.0.39');g.t(0,44,'Up '+humanDuration(UPT));g.t(0,54,'FW 1.14.0');mgr(g,'play')});
def('ipif-down',g=>{hdr(g,'Overview',5,0);const cx=64;g.bm(cx-4,24,X_ICON,8,8,1);g.t(cx-36,40,'DISCONNECTED');g.t(cx-45,52,'Check LAN Cable');mgr(g,'play')});

/* Notify (WidgetNotify.cpp) */
const NW=['Ready','Sending','Muted','Locked','Waiting','Waiting','Error'],NB=[BADGE_OK,null,null,BADGE_LOCK,BADGE_CLOCK,BADGE_CLOCK,BADGE_ERR];
function notifyMain(g,mode,sub,pages,page){const ex=W/2-20;g.rc(ex,1,40,27,1);g.ln(ex,1,ex+20,16,1);g.ln(ex+39,1,ex+20,16,1);if(pages>1)dots(g,pages,page);
  if(mode===1){g.hl(ex-14,6,8,1);g.hl(ex-18,13,12,1);g.hl(ex-12,20,6,1)}
  if(mode===2){for(let o=-2;o<=2;o++)if(o)g.ln(ex-4,1+o,ex+44,29+o,0);g.ln(ex-4,1,ex+44,29,1)}
  if(NB[mode]){g.fci(ex+39,24,10,0);badge(g,ex+39,24,NB[mode])}centered(g,33,NW[mode],2);centered(g,54,sub,1);mgr(g,'play')}
def('notify-ready',g=>notifyMain(g,0,duration(12*60,'ago'),2,0));
def('notify-sending',g=>notifyMain(g,1,'2 queued',2,0));
def('notify-muted',g=>notifyMain(g,2,duration(45*60,'left'),2,0));
def('notify-locked',g=>notifyMain(g,3,'3 queued',2,0));
def('notify-error',g=>notifyMain(g,6,'Phone push +1',3,0));
def('notify-accounts',g=>{hdr(g,'Accounts',3,1);[['Home mail',ROW_OK],['Team mail',ROW_OK],['Phone push',ROW_ERR],['Spare',ROW_NONE]].forEach((a,i)=>{const y=14+i*10;g.bm(0,y-1,a[1],9,9,1);g.t(12,y,a[0])});mgr(g,'play')});
def('notify-fault',g=>{hdr(g,'Error',3,2);badge(g,9,23,BADGE_ERR);g.t(24,14,'Phone push');g.t(24,24,duration(3*3600,'ago'));g.t(0,40,'no connection');mgr(g,'play')});

/* Network (WidgetNetSpeed.cpp) */
function netArrow(g,x,y,up){up?g.ft(x,y+5,x+2,y,x+4,y+5,1):g.ft(x,y,x+2,y+5,x+4,y,1)}
function netRate(g,x,xEnd,v){const val=humanCount(v),unit='P/s',len=val.length;const sz=(x+len*12+unit.length*6<=xEnd)?2:1;g.t(x,sz===2?12:16,val,sz);g.t(x+len*6*sz,16,unit,1)}
def('netspeed',(g,t)=>{const tx=series(128,t,4,8,40,60),rx=series(128,t,5,300,1400,2500);let sc=1;tx.forEach(v=>{if(v>sc)sc=v});rx.forEach(v=>{if(v>sc)sc=v});
  g.fr(1,3,2,4,1);g.fr(4,1,2,6,1);g.fr(7,4,2,3,1);g.t(12,0,'NETWORK');g.ln(0,10,W,10,1);
  netArrow(g,2,14,true);netRate(g,8,66,tx[127]);netArrow(g,66,14,false);netRate(g,72,W,rx[127]);
  const mid=48,half=15;for(let i=0;i<W;i+=3)g.px(i,mid,1);for(let i=0;i<W;i++){const k=127-i,x=W-1-i;let tb=tr(tx[k]*half/sc),rb=tr(rx[k]*half/sc);if(tb>half)tb=half;if(rb>half)rb=half;if(tb>0)g.vl(x,mid-tb,tb,1);if(rb>0)g.vl(x,mid+1,rb,1)}
  const pk=humanCount(sc);g.fr(0,31,pk.length*6+2,9,0);g.t(1,32,pk);mgr(g,'play')},true);

/* Time (WidgetTime.cpp) */
const WD=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
function drawTime(g,d){const p=n=>String(n).padStart(2,'0');const hm=p(d.getHours())+':'+p(d.getMinutes()),ss=':'+p(d.getSeconds());
  const hmW=hm.length*18,tot=hmW+3+ss.length*6;let sx=tr((W-tot)/2);if(sx<0)sx=0;g.t(sx,6,hm,3);g.t(sx+hmW+3,6+24-8,ss,1);
  const ds=`${WD[d.getDay()]}, ${p(d.getDate())}.${p(d.getMonth()+1)}.${d.getFullYear()}`;ctext(g,36,ds);ctext(g,56,'Uptime  '+humanDuration(UPT))}
def('time',g=>{drawTime(g,new Date());mgr(g,'play')},true);

