def('ota',(g,t)=>{const pc=tr((t*9)%101);g.t(0,0,'  www.OpenKNX.de');if(Math.floor(t*2)%2)g.fr(120,0,6,6,1);g.t(4,16,'OTA UPDATE',2);const b=pc+' %';g.t(tr((W-b.length*12)/2),34,b,2);g.rc(14,56,100,7,1);if(pc>0)g.fr(14,56,tr(100*pc/100),7,1)},true);
function sysinfo(g,wrap){g.wrap=wrap;g.t(0,0,'System Info:\n');g.pr('Time: 2026-11-10 12:34:56\n');g.pr('Addr.: 1.1.250\n');g.wrap=true;g.bm(tr((W-33)/2),tr((H-33+20)/2),LOGO33,33,33,1)}
