function keycap(g,x,y,k,inv){const w=k.length*6+3;inv?g.frr(x,y,w,9,2,1):g.rr(x,y,w,9,2,1);g.t(x+2,y+1,k,1,inv?0:1);return w}
function hint(g,x,y,k,label){const w=keycap(g,x,y,k,true);g.t(x+w+3,y+1,label);return w+3+label.length*6}
function pill(g,x,y,s){const w=s.length*6+5;g.frr(x,y,w,9,4,1);g.t(x+3,y+1,s,1,0);return w}
function spinner(g,cx,cy,t){const f=tr(t*8)%8;for(let i=0;i<8;i++){const a=i*Math.PI/4,x=cx+R(5*Math.cos(a)),y=cy+R(5*Math.sin(a));i===f?g.fci(x,y,1,1):g.px(x,y,1)}}
function ringCd(g,cx,cy,r,p){for(let a=0;a<360;a+=2){const rad=(a-90)*Math.PI/180,x=cx+R(r*Math.cos(rad)),y=cy+R(r*Math.sin(rad));if(a/360<=p){g.px(x,y,1);g.px(cx+R((r-1)*Math.cos(rad)),cy+R((r-1)*Math.sin(rad)),1)}else if(a%12===0)g.px(x,y,1)}}
