function toastB(g,ev,k,n){const y=43+tr(21*(1-k));g.fr(0,y-1,W,H-y+1,0);g.rr(1,y,126,20,3,1);const ic=ico9(ev.ico);g.bm(5,y+5,ic.d,ic.w,ic.h,1);g.wrap=false;
  g.t(18,y+2,trunc(ev.l1,n>1?84:104));if(n>1){const s='x'+n;g.t(122-s.length*6,y+2,s)}if(ev.l2)g.t(18,y+11,trunc(ev.l2,104));g.wrap=true}
function toastBan(g,ev,k){const y=-11+tr(11*k);g.fr(0,y,W,11,1);const ic=ico9(ev.ico);g.bm(1,y+1,ic.d,ic.w,ic.h,0);g.wrap=false;g.t(13,y+2,trunc(ev.l1+(ev.l2?'  '+ev.l2:''),W-15),1,0);g.wrap=true}
function toastCard(g,ev){g.fr(5,9,118,49,0);g.rr(6,10,116,47,3,1);g.fci(21,25,10,0);badge(g,21,25,ev.cls==='warn'?bits(IB['badge warn'],13,13):BADGE_ERR);g.wrap=false;g.t(35,15,trunc(ev.l1,84));if(ev.l2)g.t(35,25,trunc(ev.l2,84));
  let x=11;if(ev.open)x+=hint(g,x,44,'OK','Open')+8;hint(g,x,44,'<','Close');g.wrap=true}
