function starfield(g,t){for(let i=0;i<40;i++){const z=((rnd(i,1)*3+t*0.6)%3)+0.2,x=64+R((rnd(i,2)-0.5)*128/z),y=32+R((rnd(i,3)-0.5)*64/z);g.px(x,y,1)}}
function baseScene(g,c,t){({rot:()=>SC['n-overview'].fn(g,t),menu:()=>SC['n-list'].fn(g,t),edit:()=>SC['slider'].fn(g,t),saver:()=>starfield(g,t),dim:()=>SC['n-overview'].fn(g,t),sleep:()=>{},off:()=>{},prog:()=>SC['n-progmode'].fn(g,t),ota:()=>SC['n-ota'].fn(g,t)})[c]()}
function tpDur(ev,a){return a.indexOf('K')>=0?1e9:ev.cls==='warn'?5:2.5}
function tpDraw(){const cv=document.getElementById('tpCv');if(!cv)return;const g=new G(),now=(performance.now()-T0)/1000,ev=EV[tp.ev],a=MX[ev.cls][tp.ctx];if(now-tp.t0>tpDur(ev,a)+1.8)tp.t0=now;const dt=now-tp.t0,dur=tpDur(ev,a);let woke=false;
  if(dt>=0&&dt<=dur&&a!=='X'&&a!=='Q'){let c=tp.ctx;if(a[0]==='W'){c='rot';woke=true}baseScene(g,c,now);const k=Math.max(0,Math.min(1,dt/0.3,(dur-dt)/0.3));const kind=a.replace('W','')||'T';
    if(kind==='T')toastB(g,ev,k,1);else if(kind==='B')toastBan(g,ev,k);else toastCard(g,ev)}else baseScene(g,tp.ctx,now);
  cv.style.opacity=(tp.ctx==='dim'&&!woke)?'.45':'1';paint(cv,g)}
function tpUi(){const cx=document.getElementById('tpCtx'),ex=document.getElementById('tpEv');
  cx.innerHTML=CTX.map(c=>`<button class="chipf" data-c="${c[0]}" aria-pressed="${c[0]===tp.ctx}">${c[1]}</button>`).join('');
  ex.innerHTML=EV.map((e,i)=>`<button class="chipf" data-e="${i}" aria-pressed="${i===tp.ev}">${e.l1}</button>`).join('');
  const ev=EV[tp.ev],a=MX[ev.cls][tp.ctx];document.getElementById('tpTitle').textContent=`${CLSN[ev.cls]} · ${CTX.find(c=>c[0]===tp.ctx)[1]} → ${MXN[a]}`;
  document.getElementById('tpLog').textContent=a==='X'?'Wird verworfen, nicht gezeigt.':a==='Q'?'Wartet, bis Editor, Geste, ProgMode, Update oder das ausgeschaltete Panel vorbei sind, und erscheint dann.':''}
document.getElementById('tpCtx').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;tp.ctx=b.dataset.c;tp.t0=(performance.now()-T0)/1000;tpUi();tpDraw()});
document.getElementById('tpEv').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;tp.ev=+b.dataset.e;tp.t0=(performance.now()-T0)/1000;tpUi()});
document.getElementById('tpGo').addEventListener('click',()=>{tp.t0=(performance.now()-T0)/1000});
tpUi();setInterval(()=>{const v=document.querySelector('.view[data-view="toast"]');if(v&&!v.hidden)tpDraw()},110);
