function wifiArcs(g,cx,cy,n,step,c){for(let k=1;k<=n;k++){const r=k*step;for(let a=225;a<=315;a+=Math.max(1,tr(60/r))){const rad=a*Math.PI/180;g.px(cx+R(r*Math.cos(rad)),cy+R(r*Math.sin(rad)),c);if(r>8)g.px(cx+R((r-1)*Math.cos(rad)),cy+R((r-1)*Math.sin(rad)),c)}}g.fci(cx,cy-1,Math.max(1,tr(step/3)),c)}
function btRune(g,cx,cy,s,c){const h=tr(s/2),q=tr(s/4);g.ln(cx,cy-h,cx,cy+h,c);g.ln(cx,cy-h,cx+q,cy-q,c);g.ln(cx+q,cy-q,cx-q,cy+q,c);g.ln(cx,cy+h,cx+q,cy+q,c);g.ln(cx+q,cy+q,cx-q,cy-q,c);if(s>16){g.ln(cx+1,cy-h,cx+1,cy+h,c)}}
