/* schematic QR: finder patterns + seeded modules, dark modules on a white field like drawQr(..., true) */
function fakeQr(g,x0,y0,seed){g.fr(x0,y0,64,64,1);const n=29,m=2,o=3;const fp=(cx,cy)=>{for(let j=0;j<7;j++)for(let i=0;i<7;i++){const e=i===0||j===0||i===6||j===6||(i>=2&&i<=4&&j>=2&&j<=4);if(e)g.fr(x0+o+(cx+i)*m,y0+o+(cy+j)*m,m,m,0)}};
  for(let j=0;j<n;j++)for(let i=0;i<n;i++){const inF=(i<8&&j<8)||(i>n-9&&j<8)||(i<8&&j>n-9);if(!inF&&rnd(i*31+j,seed)>0.52)g.fr(x0+o+i*m,y0+o+j*m,m,m,0)}fp(0,0);fp(n-7,0);fp(0,n-7)}

