function deg(g,x,y,sz,c=1){sz===1?g.ci(x+2,y+2,1,c):g.ci(x+3*sz-1,y+3*sz-1,sz,c)}
/* value with degree drawn as a ring (independent of the shared cp437 state) */
function tval(g,x,y,num,unit,sz){g.t(x,y,num,sz);const dx=num.length*6*sz;deg(g,x+dx,y,sz);g.t(x+dx+6*sz,y,unit,sz);return dx+6*sz*(1+unit.length)}
function tvalC(g,y,num,unit,sz){const w=(num.length+1+unit.length)*6*sz;tval(g,tr((W-w)/2),y,num,unit,sz)}
