/* ================= EXTENSION 4: toggle variants (hand-drawn bitmaps instead of GFX circles) ================= */
const TOG={
 A:{w:17,on:art(['..#############..','.###############.','###########...###','##########.....##','##########.....##','##########.....##','###########...###','.###############.','..#############..'],17),
     off:art(['..#############..','.#.............#.','#..###..........#','#.#####.........#','#.#####.........#','#.#####.........#','#..###..........#','.#.............#.','..#############..'],17)},
 B:{w:9,on:art(['#########','#.......#','#......##','#.....#.#','##...#..#','#.#.#...#','#..#....#','#.......#','#########'],9),off:art(['#########','#.......#','#.......#','#.......#','#.......#','#.......#','#.......#','#.......#','#########'],9)},
 D:{w:16,on:art(['################','################','#########.....##','#########.....##','#########.....##','#########.....##','################','################'],16),off:art(['################','#..............#','#.#####........#','#.#####........#','#.#####........#','#.#####........#','#..............#','################'],16)},
};
function togBm(g,v,x,y,on,c){const t=TOG[v];g.bm(x,y,on?t.on:t.off,t.w,v==='D'?8:9,c)}
function togTxt(on,sel){const v=on?'On':'Off';return sel?'< '+v+' >':v}
function togC(g,x,y,on,c,sel){g.t(x,y+1,togTxt(on,sel),1,c)}
function togAny(g,v,x,y,on,c,sel){v==='C'?togC(g,x,y,on,c,sel):togBm(g,v,x,y,on,c)}
def('tog-var',g=>{g.t(0,0,'off');g.t(30,0,'on');g.t(70,0,'selected');g.hl(0,9,W,1);['A','B','C','D'].forEach((v,i)=>{const y=12+i*13;g.t(0,y+1,v);togAny(g,v,10,y,false,1);togAny(g,v,36,y,true,1);g.fr(62,y-2,66,13,1);if(v==='C'){togC(g,70,y,true,0,true)}else{togAny(g,v,68,y,false,0);togAny(g,v,98,y,true,0)}})});
