function bars4(g,x,y,lv,c=1){for(let i=0;i<4;i++){const h=2+i*2;i<lv?g.fr(x+i*3,y+8-h,2,h,c):g.hl(x+i*3,y+7,2,c)}}
const NETS=[['MyHome',-52,1],['MyHome-Guest',-58,1],['Garage AP',-71,1],['FRITZ!Box 7590',-77,1],['Cafe Open',-83,0],['Neighbour-5G',-86,1]];
function scanList(g,sel){nhdrR(g,'WiFi',(sel+1)+'/'+(NETS.length+2));const items=NETS.concat([['Other network...',0,2],['Scan again',0,3]]);let top=sel>=5?sel-4:0;
  for(let r=0;r<5&&top+r<items.length;r++){const i=top+r,n=items[i],y=12+r*10,s=i===sel,fg=s?0:1,bg=s?1:0;if(s)g.fr(0,y,124,10,1);
    if(n[2]<2){bars4(g,1,y,signalLv(n[1]),fg);g.t(15,y+1,trunc(n[0],90),1,fg,bg);if(n[2]===1){const ic=ico9('lock');g.bm(113,y,ic.d,ic.w,ic.h,fg)}}else g.t(15,y+1,n[0],1,fg,bg)}
  for(let y=12;y<62;y+=2)g.px(127,y,1);const th=tr(50*5/items.length),ty=12+tr((50-th)*top/(items.length-5));g.fr(126,ty,2,th,1)}
