const KB={abc:['abcdefghijklm','nopqrstuvwxyz','0123456789.-_'],ABC:['ABCDEFGHIJKLM','NOPQRSTUVWXYZ','0123456789.-_'],sym:['!@#$%&*+=?/\\:',";,'\"()[]{}<>~^",'|`0123456789 ']};
function keyboard(g,layer,typed,kr,kc,showLast,t){g.wrap=false;g.t(0,0,'Password');const cnt=typed.length+'/63';g.t(W-2-cnt.length*6,0,cnt);g.hl(0,10,W,1);
  let shown='*'.repeat(Math.max(0,typed.length-1))+(typed.length?(showLast?typed[typed.length-1]:'*'):'');if(shown.length>19)shown='..'+shown.slice(-17);g.t(2,13,shown);if((t*2)%2<1)g.vl(2+shown.length*6,13,8,1);
  const rows=KB[layer];for(let r=0;r<3;r++)for(let c=0;c<13;c++){const x=1+c*9+1,y=24+r*10,s=r===kr&&c===kc;if(s)g.fr(x-2,y-1,9,10,1);g.t(x,y+1,rows[r][c],1,s?0:1)}
  const keys=[['aA',22],['#+',22],['<x',22],['spc',26],['Done',30]];let x=0;keys.forEach((k,i)=>{const s=kr===3&&kc===i;s?g.frr(x,54,k[1]-2,10,2,1):g.rr(x,54,k[1]-2,10,2,1);g.t(x+tr((k[1]-2-k[0].length*6)/2),55,k[0],1,s?0:1);x+=k[1]})}
