/* ================= EXTENSION 7: burn-in protection, three ways ================= */
const SHIFT=[[0,0],[1,0],[1,1],[0,1]];
function shifted(g,id,t,dx,dy,mode){const a=new G();SC[id].fn(a,t);
  if(mode==='C'){for(let y=0;y<H;y++)a.b[y*W+W-1]=0;for(let x=0;x<W;x++)a.b[(H-1)*W+x]=0}
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){let sx=x-dx,sy=y-dy;if(mode==='B'){sx=x;sy=(y-dy+H)%H}if(sx<0||sy<0||sx>=W||sy>=H)continue;if(a.b[sy*W+sx])g.px(x,y,1)}}
def('bi-a',(g,t)=>{const s=SHIFT[tr(t/1.2)%4];shifted(g,'p-bus',t,s[0],s[1],'A')},true);
