/* ================= EXTENSION 8: optimised text editor (keeps the size-2 character wheel) ================= */
const CS_GROUPS=[['abc','abcdefghijklmnopqrstuvwxyz'],['ABC','ABCDEFGHIJKLMNOPQRSTUVWXYZ'],['123','0123456789'],['#+=',' !"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~']];
const CS=CS_GROUPS.map(x=>x[1]).join('');
function editorNeu(g,label,text,cur,mask,t,max){g.wrap=false;g.t(0,0,label);const cnt=text.length+'/'+max;g.t(W-2-cnt.length*6,0,cnt);g.hl(0,10,W,1);
  const vis=10,start=cur>=vis?cur-vis+1:0,on=(t*2)%2<1;
  for(let i=start;i<text.length&&i<start+vis;i++){const x=4+(i-start)*12,c=(mask&&i!==cur)?'*':text[i];if(i===cur){if(on){g.fr(x-1,13,13,17,1);g.t(x,14,c,2,0,1)}}else g.t(x,14,c,2,1,0)}
  const ch=text[cur],k=CS.indexOf(ch);for(let d=-4;d<=4;d++){const c=CS[(k+d+CS.length)%CS.length],x=61+d*12;if(d===0){g.fr(x-3,32,11,11,1);g.t(x,34,c===' '?'_':c,1,0,1)}else g.t(x,34,c===' '?'_':c,1)}
  const gi=CS_GROUPS.findIndex(gr=>gr[1].includes(ch));CS_GROUPS.forEach((gr,i)=>{const x=10+i*30;if(i===gi){g.frr(x-3,45,gr[0].length*6+5,10,2,1);g.t(x,46,gr[0],1,0)}else g.t(x,46,gr[0],1,1)});
  g.t(0,56,'OK=done ^v hold=group')}
def('wf-ted-neu',(g,t)=>{const s='Sun!Rise#2026',k=Math.min(s.length,4+tr(t/1.5)%(s.length-3));editorNeu(g,'Password',s.slice(0,k),k-1,true,t,63)},true);
