/* ---------- canvas paint + scheduler ---------- */
/* web = device web interface live view (display.js): lit #449841 on #071407 */
const PAL={web:['#449841','#449841'],white:['#eef5ff','#eef5ff'],blue:['#86d3ff','#86d3ff']};
function paint(cv,g){const S=cv.width/g.w,x=cv.getContext('2d');x.fillStyle=state.panel==='web'?'#071407':'#030404';x.fillRect(0,0,cv.width,cv.height);
  if(state.grid&&S>=3){x.fillStyle=state.panel==='web'?'#0d220d':'#0c1210';for(let y=0;y<g.h;y++)for(let i=0;i<g.w;i++)if(!g.b[y*g.w+i])x.fillRect(i*S+.5,y*S+.5,S-1,S-1)}
  for(let y=0;y<g.h;y++){x.fillStyle=(PAL[state.panel]||PAL.web)[1];for(let i=0;i<g.w;i++)if(g.b[y*g.w+i])x.fillRect(i*S,y*S,S,S)}
  if(state.grid&&S>=3){x.fillStyle='rgba(0,0,0,.38)';for(let i=1;i<g.w;i++)x.fillRect(i*S-.5,0,1,cv.height);for(let y=1;y<g.h;y++)x.fillRect(0,y*S-.5,cv.width,1)}}
const T0=performance.now();const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
function render(cv){const id=cv.dataset.s,sc=SC[id];if(!sc)return;const g=new G(W,sc.h||H);const t=reduce?6:(performance.now()-T0)/1000+6;sc.fn(g,t);paint(cv,g)}
let visible=new Set();
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)visible.add(e.target);else visible.delete(e.target)}),{rootMargin:'100px'});
function hook(root){root.querySelectorAll('canvas[data-s]').forEach(cv=>{render(cv);if(SC[cv.dataset.s]&&SC[cv.dataset.s].anim)io.observe(cv)})}
function repaintAll(){document.querySelectorAll('canvas[data-s]').forEach(render);simDraw();icShow(icSel)}
let last=0;function tick(ts){if(!reduce&&ts-last>240){last=ts;visible.forEach(cv=>{if(cv.offsetParent)render(cv)});heroStep()}requestAnimationFrame(tick)}

/* hero rotation */
const HERO=['s-ipif','n-overview','p-tunnels','p-bus','notify-ready','n-netspeed','w-online','s-sys'];let heroI=0,heroT=performance.now();
SC.hero={fn:(g,t)=>SC[HERO[heroI]].fn(g,t),anim:true};
function heroStep(){if(performance.now()-heroT>3200){heroT=performance.now();heroI=(heroI+1)%HERO.length}}

