function buildPool(f){const host=document.getElementById('pool');host.innerHTML=POOL.map(m=>{const its=m.items.filter(i=>f==='all'||i[2]===f);if(!its.length)return'';
  return `<div class="mod"><h3>${m.mod} · ${its.length}</h3><div class="grid">${its.map(i=>`<figure class="scr"><div class="bez"><canvas width="512" height="256" data-s="${i[0]}"></canvas></div><figcaption><span class="chip ${i[2]}">${i[2]==='ist'?'IST':'NEU'}</span><b>${i[1]}</b><span class="note">${i[3]}</span></figcaption></figure>`).join('')}</div></div>`}).join('');hook(host)}
