/* ---------- menu simulator (model of Menu.cpp behaviour) ---------- */
const sim={mode:'root',sel:0,dsel:0,m:{br:9,inv:false,ap:true,icon:false,sv:5},rsel:0,rtop:0,ssel:0,csel:0,neu:true,log:'Menü offen. OK öffnet, ← schließt in der Wurzel.'};
function simDraw(){const cv=document.getElementById('simCv');if(!cv)return;const g=new G();let title='Menü',src='Menu.cpp · drawMenu';
  if(sim.mode==='closed'){SC['ipif-overview'].fn(g,6);title='Startbildschirm';src='Rotation, OK öffnet das Menü'}
  else if(sim.mode==='root'){sim.neu?nlist(g,'Menu',ROOT,sim.sel):(sim.m.icon?iconGrid(g,ROOT,sim.sel,false):menuList(g,ROOT,sim.sel));title=sim.m.icon&&!sim.neu?'Icon-Menü':'Wurzel'}
  else if(sim.mode==='display'){const it=displayItems(sim.m);sim.neu?nlist(g,'Display',it,sim.dsel):menuList(g,it,sim.dsel);title='Display'}
  else if(sim.mode==='radio'){sim.rtop=radio(g,'Screensaver',SAVERS,sim.rsel,sim.rtop);title='Screensaver';src='Menu.cpp · drawRadioSelect'}
  else if(sim.mode==='slider'){slider(g,'Brightness',BRIGHT,sim.ssel);title='Brightness';src='Menu.cpp · drawSlider'}
  else if(sim.mode==='confirm'){confirm(g,'Reset','Reset all display values?',sim.csel);title='Reset';src='Menu.cpp · drawConfirmDialog'}
  else if(sim.mode==='other'){g.t(2,2,'(not modelled)');title='Untermenü';src='nur Display ist nachgebaut'}
  paint(cv,g);document.getElementById('simTitle').textContent=title;document.getElementById('simSrc').textContent=src;document.getElementById('simLog').textContent=sim.log}
function simKey(k){const s=sim;const di=displayItems(s.m);
  if(s.mode==='closed'){if(k==='O'){s.mode='root';s.log='OK: Menü geöffnet'}else s.log=(k==='L'||k==='R')?'Widget gewechselt':'Seite gewechselt'}
  else if(s.mode==='root'){const grid=s.m.icon&&!s.neu;
    if(grid){const cols=3,n=ROOT.length,c=s.sel%cols;if(k==='R'&&c<cols-1&&s.sel+1<n)s.sel++;else if(k==='L'&&c>0)s.sel--;else if(k==='D'){if(s.sel+cols<n)s.sel+=cols;else if(tr(s.sel/cols)<tr((n-1)/cols))s.sel=n-1}else if(k==='U'&&s.sel>=cols)s.sel-=cols;else if(k==='O')enter();s.log=k==='O'?s.log:'Icon-Raster: Pfeile bewegen, nur OK öffnet, ← lang schließt'}
    else{if(k==='U'&&s.sel>0)s.sel--;else if(k==='D'&&s.sel<ROOT.length-1)s.sel++;else if(k==='L'){s.mode='closed';s.log='←: Menü geschlossen'}else if(k==='O'||k==='R')enter();else s.log='Ende der Liste, die Auswahl bleibt stehen'}}
  else if(s.mode==='display'){if(k==='U'&&s.dsel>0)s.dsel--;else if(k==='D'&&s.dsel<di.length-1)s.dsel++;else if(k==='L'){s.mode='root';s.log='←: zurück zur Wurzel'}
    else if(k==='O'||k==='R'){const it=di[s.dsel];if(it.l==='Invert'){s.m.inv=!s.m.inv;s.log='Invert umgelegt'}else if(it.l==='Auto paging'){s.m.ap=!s.m.ap;s.log='Auto paging umgelegt'}else if(it.l==='Icon menu'){s.m.icon=!s.m.icon;s.log='Icon menu umgelegt, gilt für die Wurzel'}
      else if(it.l==='Screensaver'){s.mode='radio';s.rsel=s.m.sv;s.rtop=0;s.log='Auswahlliste offen'}else if(it.l==='Brightness'){s.mode='slider';s.ssel=s.m.br;s.log='Regler offen, wirkt sofort'}else if(it.l==='Reset'){s.mode='confirm';s.csel=0;s.log='Abfrage, „No“ ist vorgewählt'}
      else if(it.l==='Back'){s.mode='root';s.log='Back: zurück'}else s.log='Zahleneditor (hier nicht nachgebaut)'}}
  else if(s.mode==='radio'){const n=SAVERS.length;if(k==='U')s.rsel=(s.rsel+n-1)%n;else if(k==='D')s.rsel=(s.rsel+1)%n;else if(k==='L'){s.mode='display';s.log='←: abgebrochen, nichts geändert'}else{s.m.sv=s.rsel;s.mode='display';s.log='Übernommen: '+SAVERS[s.rsel]}}
  else if(s.mode==='slider'){if((k==='L'||k==='D')&&s.ssel>0){s.ssel--;s.m.br=s.ssel}else if((k==='R'||k==='U')&&s.ssel<9){s.ssel++;s.m.br=s.ssel}else if(k==='O'){s.mode='display';s.log='OK: Regler verlassen'}s.log=s.mode==='slider'?'Helligkeit '+BRIGHT[s.ssel]+' (sofort)':s.log}
  else if(s.mode==='confirm'){if(k==='L')s.csel=0;else if(k==='R')s.csel=1;else if(k==='U'||k==='D')s.csel=s.csel?0:1;else if(k==='O'){s.mode='display';s.log=s.csel?'Yes: Display-Werte zurückgesetzt (Modell)':'No: nichts geändert';if(s.csel)s.m={br:9,inv:false,ap:true,icon:false,sv:5}}}
  else if(s.mode==='other'){if(k==='L'){s.mode='root';s.log='←: zurück'}}
  simDraw();
  function enter(){const it=ROOT[s.sel];if(it.l==='Display'){s.mode='display';s.dsel=0;s.log='Display geöffnet'}else if(it.l==='< Exit'){s.log='< Exit: laut Code öffnet resume() das Menü sofort wieder (am Gerät prüfen). ← schließt.'}else{s.mode='other';s.log=it.l+': nicht nachgebaut, ← zurück'}}}
document.querySelectorAll('.pad button').forEach(b=>b.addEventListener('click',()=>simKey(b.dataset.k)));
document.getElementById('sim').addEventListener('keydown',e=>{const m={ArrowUp:'U',ArrowDown:'D',ArrowLeft:'L',ArrowRight:'R',Enter:'O',' ':'O'}[e.key];if(m){e.preventDefault();simKey(m)}});

/* ---------- controls + routing ---------- */
function syncCtl(){document.querySelectorAll('#panelSeg button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.p===state.panel?'true':'false'));document.querySelectorAll('#gridSeg button').forEach(b=>b.setAttribute('aria-pressed',(b.dataset.g==='1')===state.grid?'true':'false'))}
document.getElementById('panelSeg').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.panel=b.dataset.p;save();syncCtl();repaintAll();document.querySelectorAll('.ic').forEach(c=>{const [o,w,h]=c._o;const gg=new G(24,24);drawIcon(gg,o,w,h,12,12);paint(c._cv,gg)});document.querySelectorAll('#infoRows canvas').forEach(c=>{if(c._g)paint(c,c._g)})});
document.getElementById('gridSeg').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.grid=b.dataset.g==='1';save();syncCtl();repaintAll()});
const VIEWS=['uebersicht','katalog','ansichten','module','ablaeufe','bausteine','menue','icons','graphen','toast','pool','ausblick','raster','schrift'];
function route(){let v=location.hash.replace('#','');if(!VIEWS.includes(v))v='uebersicht';document.querySelectorAll('.view[data-view]').forEach(s=>s.hidden=s.dataset.view!==v);
  document.querySelectorAll('#tabs a').forEach(a=>a.setAttribute('aria-current',a.getAttribute('href')==='#'+v?'page':'false'));
  const sec=document.querySelector(`.view[data-view="${v}"]`);sec.querySelectorAll('canvas[data-s]').forEach(render)}
addEventListener('hashchange',()=>{route();scrollTo({top:0})});
function applyMode(){const s=state.mode!=='expert';document.body.classList.toggle('simple',s);document.querySelectorAll('#modeSeg button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.m===(s?'simple':'expert')?'true':'false'))}
document.getElementById('modeSeg').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.mode=b.dataset.m;save();applyMode()});
applyMode();syncCtl();buildPool('all');if(window._catRun)_catRun();if(window._swapRender)_swapRender('all');hook(document);simDraw();route();requestAnimationFrame(tick);

/* ================= code window: our code to copy (template, building blocks, catalog functions) ================= */
const PARTS={tpl:[['WidgetMyModule.h','tpl-h'],['WidgetMyModule.cpp','tpl-cpp'],['Anmelden','tpl-reg']]};
(function(){const dlg=document.getElementById('codeDlg');if(!dlg)return;const txt=document.getElementById('codeText'),ok=document.getElementById('codeOk'),tabs=document.getElementById('codeTabs');
  function show(key){txt.textContent=CODE[key]||'';ok.textContent='';tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.k===key?'true':'false'))}
  function open(key,title){const parts=PARTS[key]||[[title||key,key]];if(!parts.every(p=>CODE[p[1]]))return;
    document.getElementById('codeTitle').textContent=title||parts[0][0];
    tabs.innerHTML=parts.length>1?parts.map(p=>`<button class="chip" data-k="${p[1]}">${p[0]}</button>`).join(''):'';tabs.hidden=parts.length<2;
    show(parts[0][1]);if(dlg.showModal)dlg.showModal();else dlg.setAttribute('open','')}
  window.openCode=open;
  tabs.addEventListener('click',e=>{const b=e.target.closest('button');if(b)show(b.dataset.k)});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-code]');if(b){open(b.dataset.code,b.dataset.title);return}
    const cv=e.target.closest('canvas[data-s]');if(!cv)return;const row=cv.closest('.catrow');
    if(row){const btn=row.querySelector('[data-code]');if(btn)open(btn.dataset.code,btn.dataset.title);return}
    if(CODE[cv.dataset.s])open(cv.dataset.s,cv.dataset.s)});
  document.getElementById('codeClose').addEventListener('click',()=>dlg.close());
  dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close()});
  document.getElementById('codeCopy').addEventListener('click',()=>{const t=txt.textContent;const done=()=>{ok.textContent='kopiert'};
    const fall=()=>{const r=document.createRange();r.selectNodeContents(txt);const sel=getSelection();sel.removeAllRanges();sel.addRange(r);try{document.execCommand('copy');done()}catch(e){ok.textContent='markiert, Strg+C'}};
    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(done,fall);else fall()});
})();
